export const CARDS = [
  {"id":1,"cat":"Geburtshilfe","q":"Was sind die FIGO-Kriterien für eine Präeklampsie?","a":"Neu aufgetretene Hypertonie (≥140/90 mmHg) nach der 20. SSW + mindestens ein weiteres Kriterium: Proteinurie ≥300 mg/24h, Thrombozytopenie <100.000/µl, Niereninsuffizienz (Kreatinin >97 µmol/l), Leberbeteiligung, Lungenödem oder neurologische/visuelle Symptome"},
  {"id":2,"cat":"Geburtshilfe","q":"Welches ist die Erstlinientherapie bei Eklampsie?","a":"Magnesiumsulfat i.v. (4–6 g Loading dose, dann 1–2 g/h Erhaltungsdosis) zur Krampfprophylaxe und -behandlung, plus antihypertensive Therapie und angestrebte Entbindung"},
  {"id":3,"cat":"Geburtshilfe","q":"Welches Medikament ist Mittel der Wahl zur antihypertensiven Therapie in der Schwangerschaft?","a":"Methyldopa (α-Methyldopa) als Mittel der 1. Wahl; alternativ Labetalol oder Nifedipin; Kontraindikation: ACE-Hemmer/Sartane"},
  {"id":4,"cat":"Geburtshilfe","q":"Was versteht man unter einem HELLP-Syndrom?","a":"Lebensbedrohliche Komplikation der Präeklampsie: Haemolysis (Hämolyse), Elevated Liver enzymes (erhöhte Leberenzyme), Low Platelets (Thrombozytopenie <100.000/µl)"},
  {"id":5,"cat":"Geburtshilfe","q":"Was ist der sFlt-1/PlGF-Quotient und wofür wird er verwendet?","a":"Verhältnis von sFlt-1 (lösliche fms-like Tyrosinkinase 1) zu PlGF (Plazentawachstumsfaktor); bei Präeklampsie erhöht. Wert >38 erhöht Risiko für Präeklampsie; hilft bei Risikoabschätzung und Verlaufskontrolle"},
  {"id":6,"cat":"Geburtshilfe","q":"Was sind Risikofaktoren für eine Präeklampsie?","a":"Primigravida, vorbestehende Hypertonie, Diabetes mellitus, Adipositas, Mehrlingsschwangerschaft, Nierenerkrankung, Antiphospholipid-Syndrom, positive Familienanamnese; kein Risikofaktor: Nikotinabusus"},
  {"id":7,"cat":"Geburtshilfe","q":"Welche Prophylaxe wird ab dem 1. Trimenon bei erhöhtem Präeklampsie-Risiko empfohlen?","a":"Low-dose Aspirin (100–150 mg/Tag) ab der 12.–16. SSW bis zur 36. SSW"},
  {"id":8,"cat":"Geburtshilfe","q":"Wie hoch ist der Anteil von Beckenendlagen am Termin?","a":"Ca. 3–4% aller Einlinge sind am Termin in Beckenendlage (BEL)"},
  {"id":9,"cat":"Geburtshilfe","q":"Was sind absolute Kontraindikationen für einen Spontangeburtversuch nach vorheriger Sectio?","a":"Vorherige vertikale (klassische) Uterotomie oder T-Schnitt, Uterusruptur in der Anamnese, mehr als 2 vorangegangene Sectiones (relative KI), sowie plazenta previa oder andere absolute Sectio-Indikationen"},
  {"id":10,"cat":"Geburtshilfe","q":"Welche Massnahmen gelten bei Verdacht auf Vena-cava-Kompressionssyndrom?","a":"Linksseitenlage der Schwangeren; dadurch Entlastung der V. cava inferior durch den Uterus"},
  {"id":11,"cat":"Geburtshilfe","q":"Was sind typische Zeichen einer Übertragung (Postmaturität) beim Neugeborenen?","a":"Lange Fingernägel, parchmentartige/rissige Haut, kein/wenig Vernix caseosa, Mekoniumfärbung der Haut, abgemagert wirkend"},
  {"id":12,"cat":"Geburtshilfe","q":"Was ist die häufigste Ursache einer postpartalen Nachblutung?","a":"Uterusatonie (ca. 70–80% der postpartalen Hämorrhagien)"},
  {"id":13,"cat":"Geburtshilfe","q":"Was ist die Erstlinientherapie bei Uterusatonie nach Oxytocin-Versagen?","a":"Sulproston (Nalador) als Second-Line; alternativ Misoprostol (Cytotec); weitere Optionen: Carbetocin, Tranexamsäure, B-Lynch-Naht, Tamponade, Embolisation oder Hysterektomie"},
  {"id":14,"cat":"Geburtshilfe","q":"Was ist ein Sheehan-Syndrom?","a":"Hypophysenvorderlappen-Nekrose nach peripartalem Schock mit schwerer Blutung; führt zu Panhypopituitarismus mit Amenorrhoe, Unfähigkeit zu stillen, Hypothyreose, Nebennierenrindeninsuffizienz"},
  {"id":15,"cat":"Geburtshilfe","q":"Was sind Indikationen für eine Lungenreifebehandlung?","a":"Drohende Frühgeburt zwischen 24+0 und 33+6 SSW; 2 Dosen Betamethason i.m. im Abstand von 24h"},
  {"id":16,"cat":"Geburtshilfe","q":"Was ist Partosure/fFN-Test und wann wird er eingesetzt?","a":"Bestimmung von fötalem Fibronektin (fFN) aus Vaginalabstrich; negativer Wert schliesst Frühgeburt innerhalb 7 Tage mit hoher Wahrscheinlichkeit aus; positiv: erhöhtes Frühgeburtsrisiko"},
  {"id":17,"cat":"Geburtshilfe","q":"Was ist ein TTTS (Twin-to-twin Transfusion Syndrom) und wie wird es behandelt?","a":"Ungleiche Versorgung monochorialer Zwillinge über Anastomosen; Donor: Oligohydramnion, Anämie; Akzeptor: Polyhydramnion, Polyglobulie; Therapie: fetoskopische Laserkoagulation der Anastomosen"},
  {"id":18,"cat":"Geburtshilfe","q":"Was ist die häufigste Fehlbildung bei Neugeborenen von Müttern mit Kokainabusus?","a":"Kokain verursacht v.a. vaskuläre Schäden: IUGR, vorzeitige Plazentalösung, zerebrovaskuläre Infarkte; Herzfehlbildungen sind weniger typisch als bei Alkohol"},
  {"id":19,"cat":"Geburtshilfe","q":"Wie hoch ist die Rate an postpartalen Depressionen?","a":"Ca. 10–15% der Mütter entwickeln eine postpartale Depression; Baby Blues ist eine mildere und häufigere Form (ca. 50–80%), tritt meist 3.–5. Tag auf und ist selbstlimitierend"},
  {"id":20,"cat":"Geburtshilfe","q":"Was ist eine Fruchtwasserembolie und welche Symptome treten auf?","a":"Seltene, lebensbedrohliche Komplikation; Fruchtwasserbestandteile gelangen in mütterlichen Kreislauf; Symptome: plötzliche Hypotonie, Dyspnoe, Tachykardie, Kreislaufkollaps, DIC, neurologische Symptome"},
  {"id":21,"cat":"Geburtshilfe","q":"Welches sind Komplikationen einer schweren Oligohydramnie?","a":"Fetale Lungenhypoplasie (häufigste Todesursache), Extremitätendeformitäten, Gesichtsdeformitäten (Potter-Sequenz), Nabelschnurkompression; Niereninsuffizienz ist Ursache, nicht Komplikation"},
  {"id":22,"cat":"Geburtshilfe","q":"Was versteht man unter einem Polyhydramnion und welche Ursachen gibt es?","a":"Fruchtwassermenge >2000 ml (AFI >25 cm); Ursachen: Gestationsdiabetes, fetale Schluckstörungen, Ösophagusatresie, neurologische Fehlbildungen, Anämie (Hydrops fetalis)"},
  {"id":23,"cat":"Geburtshilfe","q":"Was ist das Vorgehen bei einer Mastitis puerperalis?","a":"Weiterstillen oder Abpumpen, lokale Kühlung, Analgesie; bei bakterieller Mastitis: Antibiotika (Dicloxacillin/Flucloxacillin oder Cephalexin); häufigster Erreger: S. aureus; tritt meist 2.–4. Woche postpartal auf"},
  {"id":24,"cat":"Geburtshilfe","q":"Was sind erhöhte Risiken bei einer Gemini-Schwangerschaft?","a":"Frühgeburtlichkeit, perinatale Mortalität, SS-induzierte Hypertonie/Präeklampsie, Fehlbildungen (v.a. monochorial), Wachstumsrestriktion (IUGR), TTTS (bei monochoralen Zwillingen)"},
  {"id":25,"cat":"Geburtshilfe","q":"Was ist bei einer Schwangeren in der 31. SSW mit RR 160/95 mmHg, Kopfschmerzen und Reflexhyperreflexie das geeignete Antihypertensivum?","a":"Labetalol i.v. oder Hydralazin i.v. für akute schwere Hypertonie; oral: Methyldopa, Labetalol oder Nifedipin; Magnesiumsulfat zur Eklampsie-Prophylaxe; Ramipril ist kontraindiziert"},
  {"id":26,"cat":"Geburtshilfe","q":"Wie wird die Spezifität eines diagnostischen Tests berechnet?","a":"Spezifität = TN / (TN + FP); d.h. Anteil der Gesunden, die korrekt als negativ erkannt werden"},
  {"id":27,"cat":"Geburtshilfe","q":"Welche Komplikationen treten häufig bei frühgeborenen Kindern auf?","a":"Atemnotsyndrom (RDS), Hyperbilirubinämie, Hypoglykämie, Hypothermie, intraventrikuläre Blutung (IVH), nekrotisierende Enterokolitis (NEC), Infektanfälligkeit"},
  {"id":28,"cat":"Geburtshilfe","q":"Was ist das sinusoidale CTG und was deutet es an?","a":"Sinusoidal: gleichmässige, sinusförmige Oszillation (Amplitude 5–15 bpm, 2–5 Zyklen/min) ohne Akzelerationen; deutet auf fetale Anämie hin (z.B. Rhesus-Inkompatibilität, Parvovirus B19)"},
  {"id":29,"cat":"Geburtshilfe","q":"Was ist die Therapie bei einem Twin-to-twin Transfusion Syndrom (TTTS) Grad III–IV?","a":"Fetoskopische Laserkoagulation der plazentaren Anastomosen; Amniodrainage als Alternative bei milderen Formen"},
  {"id":30,"cat":"Geburtshilfe","q":"Was ist eine mentoposteriore Einstellung und wie wird sie behandelt?","a":"Gesichtslage mit Kinn dorsal; Spontangeburt unmöglich; Behandlung: Sectio caesarea"},
  {"id":31,"cat":"Geburtshilfe","q":"Welche Abklärung ist bei sinusoidalem CTG und Polyhydramnion in der 33. SSW prioritär?","a":"Parvovirus B19-Serologie (häufigste Ursache fetaler Anämie), irreguläre Antikörper (Rhesus-Inkompatibilität), MCA-Doppler zur Beurteilung fetaler Anämie"},
  {"id":32,"cat":"Geburtshilfe","q":"Was ist eine Missed Abortion?","a":"Abgestorbener Embryo/Fetus im Uterus ohne Austreibung; kein Herzschlag nachweisbar; klinisch oft keine Blutung; Therapie: abwartend, medikamentös (Misoprostol) oder chirurgisch (Kürettage)"},
  {"id":33,"cat":"Geburtshilfe","q":"Welches sind Zeichen des Vena-cava-Syndroms in der Schwangerschaft?","a":"Hypotonie, Schwindel, Synkope bei Rückenlage durch Kompression der V. cava inferior; Therapie: Linksseitenlage"},
  {"id":34,"cat":"Geburtshilfe","q":"Was sind Zeichen einer Plazenta accreta/percreta?","a":"Abnormales Eindringen in Myometrium (accreta) oder vollständige Durchwachsung (percreta); Risikofaktor: Z.n. Sectio; Vorgehen: Aufklärung über Sectio-Hysterektomie, Blutkonserven bereitstellen, fundale Uterotomie"},
  {"id":35,"cat":"Geburtshilfe","q":"Was ist ein Gestationsdiabetes und wie wird er therapiert?","a":"Erstmalige Glukosetoleranzstörung in der SS; Therapie: Diät + Blutzuckerkontrollen; bei unzureichender Einstellung: Insulintherapie; Entbindung spätestens 38+0 SSW bei GDM mit Insulintherapie"},
  {"id":36,"cat":"Geburtshilfe","q":"Was ist das biophysikalische Profil nach Manning?","a":"Sonographische Beurteilung: CTG-Reaktivität, fetale Atembewegungen, Körperbewegungen, Tonus, Fruchtwassermenge; Bewertung 0–10 Punkte; ≤4 Punkte: pathologisch, Entbindung erwägen"},
  {"id":37,"cat":"Geburtshilfe","q":"Was ist der Kleihauer-Betke-Test?","a":"Nachweis fetaler Erythrozyten im mütterlichen Blut (fetomaternale Transfusion); Indikation: Trauma in der SS oder nach Entbindung bei Rh-negativer Mutter zur Dosierung der Anti-D-Prophylaxe"},
  {"id":38,"cat":"Geburtshilfe","q":"Was sind Risiken einer Schwangerschaft bei Frauen ≥40 Jahre?","a":"Atonie, höhergradige Dammrisse, Frühgeburt, Gestationsdiabetes, Präeklampsie, chromosomale Anomalien (Trisomie 21 häufiger), erhöhte Sectio-Rate"},
  {"id":39,"cat":"Geburtshilfe","q":"Was sind Komplikationen einer Hyperemesis gravidarum?","a":"Wernicke-Enzephalopathie (Thiaminmangel), Elektrolytimbalanz, Mangelernährung, Dysthymie/Depression; kein direkter Zusammenhang mit Gerinnungsstörungen"},
  {"id":40,"cat":"Geburtshilfe","q":"Was sind Indikationen für eine Notfallsectio im CTG?","a":"Anhaltende schwere Bradykardie, wiederholte späte Dezelerationen, Saltatorium, Sinusoidalmuster; Vogelschwingen-Muster: Zeichen schwerer fetaler Asphyxie → sofortige Sectio"},
  {"id":41,"cat":"Geburtshilfe","q":"Welche Schwangerschaft hat das höchste Risiko für Uterusruptur?","a":"Z.n. Sectio mit klassischer (vertikaler) Uterotomie; bei querer Schnittführung geringeres Risiko; VBAC möglich mit Rupturrisiko 0,5–0,9%"},
  {"id":42,"cat":"Geburtshilfe","q":"Was verursacht IUGR (intrauterine Wachstumsretardierung)?","a":"Nikotinabusus, Alkohol, Kokain, Amphetamine, Hypertonie, Präeklampsie, Plazentainsuffizienz, Chromosomenfehler, Infektionen; Marihuana und Opiate sind schwächere Risikofaktoren"},
  {"id":43,"cat":"Geburtshilfe","q":"Was ist die Lochiometra?","a":"Verhaltenes Wochenbett (Lochialstau im Uterus); Ursachen: Zervixspasmus, Plazentareste; Symptome: Fieber, Unterbauchschmerzen, sistierte Lochien; Therapie: Uterustonika, Kürettage bei Resten"},
  {"id":44,"cat":"Geburtshilfe","q":"Was ist eine PTBS nach der Geburt?","a":"Posttraumatische Belastungsstörung nach traumatischer Geburterfahrung; Symptome: Flashbacks, Albträume, Hyperarousal, Vermeidungsverhalten; Abgrenzung von Baby Blues und postpartaler Depression"},
  {"id":45,"cat":"Gynäkologie","q":"Was sind die Rotterdam-Kriterien für das PCO-Syndrom?","a":"Mindestens 2 von 3: Oligo-/Anovulation, klinische oder biochemische Hyperandrogenämie, polyzystische Ovarien im Ultraschall (≥12 Follikel oder Ovarvolumen >10 ml); Insulinresistenz und LH/FSH >2 sind kein offizielles Kriterium"},
  {"id":46,"cat":"Gynäkologie","q":"Welches Medikament wird zur Ovulationsinduktion bei PCOS mit Kinderwunsch bevorzugt?","a":"Letrozol (Aromatasehemmer, off-label) als First-line; alternativ Clomifen; bei Insulinresistenz: Metformin als Zusatz"},
  {"id":47,"cat":"Gynäkologie","q":"Wann und wie wird der AMH-Wert bestimmt?","a":"AMH kann zyklusunabhängig bestimmt werden; reflektiert die ovarielle Reserve; erniedrigt = reduzierte Reserve; erhöht = PCOS"},
  {"id":48,"cat":"Gynäkologie","q":"Was sind die Symptome einer Hymenalatresie?","a":"Primäre Amenorrhoe, zyklische Unterbauchschmerzen (Hämatokolpos), Harnverhalt durch Kompression der Urethra; Therapie: operative Inzision"},
  {"id":49,"cat":"Gynäkologie","q":"Was ist das MRKH-Syndrom?","a":"Aplasie/Hypoplasie von Uterus und oberem Vaginalanteil bei normalem weiblichem Phänotyp (46,XX) und normalen Ovarien; primäre Amenorrhoe, normale Pubertätsentwicklung"},
  {"id":50,"cat":"Gynäkologie","q":"Was ist das Androgen-Insensitivitäts-Syndrom (AIS, komplette Form)?","a":"Genetisch männlich (46,XY), vollständige Androgenresistenz; phänotypisch weiblich, kein Uterus, keine Schambehaarung, primäre Amenorrhoe; Gonaden: intraabdominale Hoden"},
  {"id":51,"cat":"Gynäkologie","q":"Was ist ein Lichen sclerosus der Vulva und wie wird er therapiert?","a":"Chronisch entzündliche Dermatose mit weisslichen Plaques, Juckreiz, Atrophie; erhöhtes Vulvakarzinom-Risiko; Therapie: hochpotente Kortikosteroide (Clobetasol) lokal"},
  {"id":52,"cat":"Gynäkologie","q":"Was ist Vaginismus und wie wird er behandelt?","a":"Unwillkürliche Kontraktion der Beckenbodenmuskulatur bei Penetrationsversuch; Behandlung: Beckenbodenphysiotherapie, Psychotherapie, graduierte Dilatation"},
  {"id":53,"cat":"Gynäkologie","q":"Was sind die Symptome einer Endometriose?","a":"Dysmenorrhoe, Dyspareunie, chronische Unterbauchschmerzen, Dyschezie, Infertilität; typisch: Endometriome (Schokoladenzysten), retrozervikale Herde"},
  {"id":54,"cat":"Gynäkologie","q":"Wie wird ein Endometriom behandelt?","a":"Laparoskopische Zystektomie (nicht Drainage allein); GnRH-Analoga zur medikamentösen Suppression; bei Kinderwunsch in 2–3 Jahren: Dienogest-Pille"},
  {"id":55,"cat":"Gynäkologie","q":"Was sind Zeichen einer Ovarialtorsion im Ultraschall?","a":"Vergrössertes Ovar, fehlender Blutfluss im Doppler, freie Flüssigkeit; klinisch: plötzlicher, starker, einseitiger Unterbauchschmerz; Therapie: sofortige operative Detorsion"},
  {"id":56,"cat":"Gynäkologie","q":"Was ist Fitz-Hugh-Curtis-Syndrom?","a":"Perihepatitis als Komplikation einer PID, meist durch Chlamydien; Symptome: akute Schmerzen im rechten Oberbauch; Verwachsungen: 'violinstrings'"},
  {"id":57,"cat":"Gynäkologie","q":"Was ist das Asherman-Syndrom?","a":"Intrauterine Synechien nach mechanischem Trauma (Kürettage, Infektion); führt zu sekundärer Amenorrhoe, Infertilität; Diagnose/Therapie: Hysteroskopie mit Adhäsiolyse"},
  {"id":58,"cat":"Gynäkologie","q":"Was sind Zeichen einer bakteriellen Vaginose?","a":"Amingeruch, grau-weisslicher homogener Ausfluss, Clue cells im Nativpräparat, pH >4,5, positiver Amintest (KOH); Erreger: Gardnerella vaginalis + Anaerobier; Therapie: Metronidazol"},
  {"id":59,"cat":"Gynäkologie","q":"Was sind Symptome einer Trichomonadeninfektion und wie wird sie behandelt?","a":"Schaumig-grüner Ausfluss, Juckreiz, Brennen, Kolpitis; Nachweis: begeisselte Protozoen im Nativpräparat; Therapie: Metronidazol 2g oral einmalig + Partnerbehandlung"},
  {"id":60,"cat":"Gynäkologie","q":"Was ist ein Tuboovarialabszess?","a":"Eitrige Einschmelzung von Tube und Ovar; Symptome: Fieber, Leukozytose, Portioschiebeschmerz, tastbare Adnexraumforderung; Therapie: Antibiotika i.v. +/- operative Drainage"},
  {"id":61,"cat":"Gynäkologie","q":"Welches Vorgehen ist bei HSIL im PAP-Abstrich indiziert?","a":"Kolposkopie mit gezielter Biopsie zur histologischen Sicherung; je nach Befund: Konisation; nicht primär Hysterektomie"},
  {"id":62,"cat":"Gynäkologie","q":"Was sind Symptome einer Zystozele?","a":"Blasensenkung mit Fremdkörpergefühl, Miktionsproblemen, Inkontinenz, Harnretention; Therapie: Beckenbodentraining, Pessartherapie, operative Deszensusplastik"},
  {"id":63,"cat":"Gynäkologie","q":"Was ist die Ätiologie eines Uterus unicornis?","a":"Einseitige Aplasie/Atresie des Müller-Gangs; halbseitiger Uterus mit nur einem Tubenansatz; assoziiert mit Nierenfehlbildungen auf gleicher Seite"},
  {"id":64,"cat":"Gynäkologie","q":"Was ist eine Hysteroskopie und für was wird sie eingesetzt?","a":"Endoskopische Untersuchung des Uterus-Cavums; Diagnose und Therapie: submuköse Myome, Polypen, Synechien; diagnostische HSK + Kürettage bei postmenopausaler Blutung"},
  {"id":65,"cat":"Gynäkologie","q":"Was sind Symptome und Behandlung der Vulvodynie?","a":"Chronischer vulvärer Brennschmerz ohne erkennbare Ursache; Therapie: lokales Lidocain, Amitriptylin, Beckenbodenphysiotherapie, bei Versagen: Vestibulektomie"},
  {"id":66,"cat":"Gynäkologie","q":"Was sind Nebenwirkungen von GnRH-Analoga und worüber muss die Patientin aufgeklärt werden?","a":"Hypöstrogenismus: Hitzewallungen, Knochendichtverlust (wichtigste NW bei Langzeitanwendung), Libidoverlust; Add-back-Therapie empfohlen; max. Therapiedauer ohne Add-back: 6 Monate"},
  {"id":67,"cat":"Gynäkologie","q":"Was ist eine Salpingitis isthmica nodosa?","a":"Noduläre Verdickung des isthmischen Tubenanteils; assoziiert mit Infertilität und erhöhtem Ektopie-Risiko; Diagnose: Hysterosalpingographie"},
  {"id":68,"cat":"Gynäkologie","q":"Was sind die Symptome einer ektopen Schwangerschaft?","a":"Amenorrhoe, vaginale Schmierblutung, einseitiger Unterbauchschmerz; bei Ruptur: akutes Abdomen, Schock; Beta-HCG positiv, leerer Uterus; Therapie: Methotrexat oder Salpingektomie/-tomie"},
  {"id":69,"cat":"Gynäkologie","q":"Was ist ein Mamma-Abszess und wie wird er therapiert?","a":"Eitrige Einschmelzung in der Brustdrüse; perkutane Inzision + Drainage; Antibiotika (S. aureus-wirksam); Abstillen nicht obligatorisch; beim Stillen: Weiterstillen möglich"},
  {"id":70,"cat":"Gynäkologie","q":"Was ist das Extramamilläre Morbus Paget der Vulva?","a":"Seltene, intraepitheliale adenokarzinomartige Erkrankung der Vulva; chronisch, therapieresistent; Bild: rötliche, weissliche, schuppende Läsion; Diagnose: Stanzbiopsie; Therapie: Exzision"},
  {"id":71,"cat":"Onkologie","q":"Welches gynäkologische Karzinom hat in der Schweiz die niedrigste 5-Jahres-Überlebensrate?","a":"Ovarialkarzinom (ca. 40–45% 5-JÜR), da meist im fortgeschrittenen Stadium (FIGO III–IV) diagnostiziert"},
  {"id":72,"cat":"Onkologie","q":"Welches gynäkologische Karzinom ist das häufigste in der Schweiz bei Frauen über 60 Jahren?","a":"Endometriumkarzinom (häufigste gynäkologische Malignität bei postmenopausalen Frauen in westlichen Ländern)"},
  {"id":73,"cat":"Onkologie","q":"Was sind die FIGO-Stadien des Zervixkarzinoms?","a":"FIGO I: auf Zervix begrenzt; FIGO II: jenseits Zervix (IIa: oberes Vaginaldrittel, IIb: Parametrienbefall); FIGO III: Beckenwand/unteres Vaginaldrittel/Hydronephrose (IIIb!); FIGO IV: Blasen-/Rektuminfiltration oder Fernmetastasen"},
  {"id":74,"cat":"Onkologie","q":"Wie unterscheidet man FIGO IIa von FIGO IIb beim Zervixkarzinom?","a":"Rektovaginale Untersuchung; IIa: oberes Vaginaldrittel, keine Parametrieninfiltration; IIb: Infiltration der Parametrien palpatorisch tastbar"},
  {"id":75,"cat":"Onkologie","q":"Was ist die Standardtherapie des Zervixkarzinoms FIGO IIb und höher?","a":"Primäre Radiochemotherapie; Cisplatin-basierte Chemotherapie als Radiosensitizer; keine operative Therapie"},
  {"id":76,"cat":"Onkologie","q":"Was ist die Therapie des Zervixkarzinoms Stadium IB bei Kinderwunsch?","a":"Trachelektomie (Zervixentfernung unter Erhalt des Uterus) bei IB1; bei Parametrienbefall oder höheren Stadien: Radiochemotherapie"},
  {"id":77,"cat":"Onkologie","q":"Was sind Indikationen zur Chemotherapie beim Mammakarzinom?","a":"Metastasierung, inflammatorisches Mammakarzinom, ausgeprägter Lymphknotenbefall, triple-negatives Karzinom, Her2-positives Karzinom, neoadjuvante Therapie bei grossen Tumoren"},
  {"id":78,"cat":"Onkologie","q":"Was ist die adjuvante Therapie nach BET bei ER/PR-positivem, Her2-negativem Mammakarzinom?","a":"Radiotherapie der Brust + Endokrintherapie: prämenopausal Tamoxifen (5–10 Jahre); postmenopausal Aromatasehemmer; keine Chemotherapie bei günstiger Genomik"},
  {"id":79,"cat":"Onkologie","q":"Was ist das Meigs-Syndrom?","a":"Ovarialtumor (meist Ovarialfibrom) mit Aszites und Pleuraerguss; nach Tumorentfernung Rückbildung; kann auch bei benignen Tumoren auftreten"},
  {"id":80,"cat":"Onkologie","q":"Was sind Risikofaktoren für das Mammakarzinom?","a":"Alter, BRCA1/2-Mutation, frühe Menarche, späte Menopause, Nulliparität, atypische duktale Hyperplasie (ADH; 4–5-fach erhöht); kein erhöhtes Risiko: einfache duktale Hyperplasie"},
  {"id":81,"cat":"Onkologie","q":"Wie lautet das Vorgehen bei postmenopausaler Blutung?","a":"Hysteroskopie und Kürettage (fraktionierte Abrasio) zur histologischen Abklärung; obligat bei jeder postmenopausalen Blutung"},
  {"id":82,"cat":"Onkologie","q":"Was ist eine Blasenmole (partielle vs. vollständige)?","a":"Vollständige: 46,XX, diandrich, kein fetales Gewebe; partielle: triploide (69,XXY), fetale Anteile vorhanden; Therapie: Saugkürettage; Nachsorge: β-HCG-Kontrollen"},
  {"id":83,"cat":"Onkologie","q":"Was ist das Vorgehen bei einem Ovarialkarzinom Stadium IIIb nach Operation?","a":"Adjuvante Chemotherapie (Carboplatin + Paclitaxel, 6 Zyklen); Ziel: maximale chirurgische Resektion (Debulking) + adjuvante Chemotherapie"},
  {"id":84,"cat":"Onkologie","q":"Was sind Indikationen für eine Kolposkopie?","a":"HSIL oder LSIL im PAP-Abstrich, HPV-positiver Test (insb. HPV 16/18), auffällige Inspektion der Zervix, Blutungssymptome"},
  {"id":85,"cat":"Onkologie","q":"Was ist das Vulvakarzinom Stadium IA und wie wird es therapiert?","a":"Tiefe <1 mm, Durchmesser ≤2 cm, keine Lymphknotenmetastasen; Therapie: Weite lokale Exzision, keine Lymphadenektomie erforderlich"},
  {"id":86,"cat":"Onkologie","q":"Was sind Zeichen eines Ovarialkarzinoms bei der Diagnose?","a":"'Omental cake', Aszites, peritoneale Aussaat; meist Stadium III/IV; Tumormarker: CA-125; Therapie: Debulking + Chemotherapie"},
  {"id":87,"cat":"Onkologie","q":"Was ist das Vorgehen bei einem Endometriumkarzinom FIGO I?","a":"Operative Therapie: totale Hysterektomie + Salpingo-Oophorektomie bds. + Lymphknotenbeurteilung; adjuvante Radiotherapie je nach Risikoklassifikation"},
  {"id":88,"cat":"Onkologie","q":"Was ist das Vorgehen bei einem palpablen Brustknoten in der Schwangerschaft?","a":"Mammasonographie als erste Bildgebung; bei suspektem Befund: Biopsie unter Sonokontrolle; kein Abwarten bis nach der Geburt"},
  {"id":89,"cat":"Onkologie","q":"Was sind ovariellen Tumoren, die mit Virilisierung assoziiert sein können?","a":"Sertoli-Leydig-Zelltumor (Androgen), Thekazelltumore; bei plötzlicher Virilisierung: Ausschluss NNR-Tumor; Granulosazelltumor produziert Östrogen"},
  {"id":90,"cat":"Reproduktionsmedizin","q":"Was ist der Unterschied zwischen IVF und ICSI?","a":"IVF: Eizelle und Spermien in vitro zusammengebracht; ICSI: einzelne Spermie direkt in Eizelle injiziert; Indikation ICSI: schwere Oligo-/Astheno-/Teratozoospermie, Azoospermie (TESE), Fertilisationsversagen bei IVF"},
  {"id":91,"cat":"Reproduktionsmedizin","q":"Bei welchen Befunden des Spermogramms wird ICSI bevorzugt gegenüber IVF?","a":"Schwere Oligoasthenozoospermie, Azoospermie mit positiver Hodenbiopsie (TESE/MESA), Fertilisationsversagen bei vorherigem IVF-Versuch"},
  {"id":92,"cat":"Reproduktionsmedizin","q":"Was sind Ursachen einer Azoospermie?","a":"Obstruktiv: Verschluss der ableitenden Samenwege (z.B. nach Vasektomie, Chlamydien-Epididymitis); nicht-obstruktiv: gestörte Spermatogenese (Klinefelter XXY, Hodentrauma, Chemotherapie)"},
  {"id":93,"cat":"Reproduktionsmedizin","q":"Was ist das Klinefelter-Syndrom?","a":"Karyotyp 47,XXY; Hochwuchs, kleine feste Hoden, Gynäkomastie, Azoospermie; FSH und LH erhöht; häufigste chromosomale Ursache der männlichen Infertilität"},
  {"id":94,"cat":"Reproduktionsmedizin","q":"Unter welchen Bedingungen ist eine Samenspende in der Schweiz legal?","a":"Samenspende in der Schweiz erlaubt für verheiratete Paare (inkl. gleichgeschlechtliche Paare nach Gesetzesänderung 2022); Voraussetzung: das Paar muss verheiratet sein"},
  {"id":95,"cat":"Reproduktionsmedizin","q":"Was ist das Vorgehen bei beidseitigem Tubenverschluss nach Chlamydien?","a":"IVF; chirurgische Tubenrekonstruktion selten sinnvoll; ICSI nur bei zusätzlicher Spermienproblematik"},
  {"id":96,"cat":"Reproduktionsmedizin","q":"Was sind Hauptursachen einer primären Amenorrhoe?","a":"Turner-Syndrom (45,X0), MRKH-Syndrom, komplette Androgenresistenz (AIS), Hymenalatresie, Hypogonadismus"},
  {"id":97,"cat":"Reproduktionsmedizin","q":"Was ist eine prämature Ovarialinsuffizienz (POI)?","a":"Ausfall der ovariellen Funktion vor dem 40. Lebensjahr; niedrige Östrogenspiegel, erhöhte FSH-Werte (>25 IU/l); Therapie: HRT bis normales Menopausenalter; Kinderwunsch: Eizellspende"},
  {"id":98,"cat":"Reproduktionsmedizin","q":"Was ist das Energie-Defizit-Syndrom (RED-S)?","a":"Relatives Energiemangelsyndrom bei Leistungssportlerinnen oder Frauen mit Untergewicht; hypothalamische Amenorrhoe, niedrige LH/FSH/Östradiol; Therapie: Gewichtszunahme, mehr Energiezufuhr"},
  {"id":99,"cat":"Infektionen / STI","q":"Welche Infektionen gehören zum TORCH-Komplex?","a":"Toxoplasmose, Other (Syphilis, VZV, Parvovirus B19, HIV), Röteln, CMV, Herpes simplex; können bei Infektion in der SS zu Fehlbildungen oder fetalen Schäden führen"},
  {"id":100,"cat":"Infektionen / STI","q":"Was sind typische Folgen einer kongenitalen CMV-Infektion?","a":"Hepatosplenomegalie, Mikrozephalie, periventrikuläre Verkalkungen, Hörminderung (häufigste Folge), IUGR, Chorioretinitis; Herzfehlbildungen sind NICHT typisch"},
  {"id":101,"cat":"Infektionen / STI","q":"Welcher Faktor beeinflusst das Übertragungsrisiko bei Toxoplasmose am meisten?","a":"Schwangerschaftsalter bei Infektion: im 1. Trimester niedrige Übertragungsrate, aber schwere Folgen; im 3. Trimester hohe Übertragungsrate, mildere Folgen"},
  {"id":102,"cat":"Infektionen / STI","q":"Was macht Parvovirus B19 in der Schwangerschaft?","a":"Aplastische Krise beim Fetus → fetale Anämie → Hydrops fetalis; sinusoidales CTG; Diagnose: MCA-Doppler, maternale Serologie; Therapie: intrauterine Transfusion"},
  {"id":103,"cat":"Infektionen / STI","q":"Was sind Komplikationen einer Chlamydien-Infektion?","a":"Salpingitis, Tuboovarialabszess, Tubenverschluss (Infertilität), Fitz-Hugh-Curtis-Syndrom, reaktive Arthritis; Abstrichentnahme: Zervix oder Urethra (NICHT Vagina)"},
  {"id":104,"cat":"Infektionen / STI","q":"Was ist die Behandlung von Chlamydien?","a":"Azithromycin 1g oral einmalig ODER Doxycyclin 100mg 2x täglich für 7 Tage; Partnerbehandlung; bei PID: Doxycyclin + Ceftriaxon +/- Metronidazol für 14 Tage"},
  {"id":105,"cat":"Infektionen / STI","q":"Welche Impfungen sind in der Schwangerschaft erlaubt?","a":"Erlaubt: Influenza (inaktiviert), Tdap (Keuchhusten), Hepatitis B, Tollwut; Kontraindiziert (Lebendimpfstoffe): MMR, Varizellen, Gelbfieber"},
  {"id":106,"cat":"Infektionen / STI","q":"Was ist das Vorgehen bei HBsAg-positiver Schwangerer?","a":"Viruslast (HBV-DNA) bestimmen; bei Geburt: aktive und passive Immunisierung des Neugeborenen innerhalb 12h; Antivirale Therapie bei hoher Viruslast; Sectio und Stillverbot sind NICHT grundsätzlich indiziert"},
  {"id":107,"cat":"Infektionen / STI","q":"Welche Hepatitis-B-Serologie zeigt Immunität nach Impfung?","a":"HBsAg negativ, Anti-HBc negativ, Anti-HBs positiv (≥10 IU/l); bei natürlicher Immunität: Anti-HBc positiv, Anti-HBs positiv, HBsAg negativ"},
  {"id":108,"cat":"Infektionen / STI","q":"Was sind die Komplikationen einer Listerien-Infektion in der Schwangerschaft?","a":"Mütterlich: grippeähnliche Symptome; fetal: IUFT, Frühgeburt, neonatale Sepsis/Meningitis; Prävention: kein Rohmilchkäse, kein rohes Fleisch/Fisch"},
  {"id":109,"cat":"Infektionen / STI","q":"Welche Erreger verursachen eine neonatale Enzephalitis am häufigsten?","a":"Herpes simplex Virus (HSV, primär HSV-2 bei Geburtskanalpassage); Prävention: Sectio bei aktivem Herpesausbruch unter der Geburt"},
  {"id":110,"cat":"Infektionen / STI","q":"Was ist Malaria in der Schwangerschaft?","a":"Besonders gefährlich in der SS; führt zu Anämie, IUGR, Frühgeburt, IUFT; Plasmodium falciparum besonders gefährlich; bei Patientin aus Endemiegebiet immer daran denken"},
  {"id":111,"cat":"Endokrinologie / Hormone","q":"Was sind Ursachen einer Galaktorrhoe?","a":"Hyperprolaktinämie: Prolaktinom (häufigste Ursache), Hypothyreose, Medikamente (Antipsychotika, Metoclopramid), Niereninsuffizienz; Abklärung: Prolaktin-Bestimmung, bei Erhöhung: MRI Hypophyse"},
  {"id":112,"cat":"Endokrinologie / Hormone","q":"Was sind Symptome eines Kraniopharyngeoms?","a":"Benigner Tumor der Hypophysenregion; Hypopituitarismus, Diabetes insipidus, bitemporale Hemianopsie, Wachstumsretardierung; häufig im Kindes- und Jugendalter"},
  {"id":113,"cat":"Endokrinologie / Hormone","q":"Was sind Zeichen und Ursachen eines Hyperandrogenismus bei Frauen?","a":"Hirsutismus, Akne, Alopezie, Klitorishypertrophie, Virilisierung; Ursachen: PCOS (häufigste), Nebennierenrindentumor, AGS (adrenogenitales Syndrom)"},
  {"id":114,"cat":"Endokrinologie / Hormone","q":"Welches Gestagen verursacht am ehesten Akne?","a":"Norethisteron (androgene Wirkung); antiandrogene Gestagene: Cyproteronacetat, Chlormadinonacetat, Dienogest, Drospirenon"},
  {"id":115,"cat":"Endokrinologie / Hormone","q":"Was sind Optionen zur Therapie perimenopausaler Hitzewallungen?","a":"HRT als wirksamste Therapie; alternativ (evidenzbasiert): SSRIs/SNRIs (Venlafaxin), Cimicifuga (begrenzte Evidenz); nicht ausreichend: Phytoöstrogene, Homöopathie"},
  {"id":116,"cat":"Endokrinologie / Hormone","q":"Welche Abklärung ist vor Beginn einer HRT prioritär?","a":"Mammographie (Ausschluss Mammakarzinom); gynäkologische Untersuchung inkl. PAP; bei postmenopausaler Blutung: Endometriumabklärung"},
  {"id":117,"cat":"Endokrinologie / Hormone","q":"Was sind absolute Kontraindikationen für die kombinierte orale Kontrazeption (KOK)?","a":"Thrombose/Embolie in der Anamnese, Migräne mit Aura, Hypertonie >160/100, östrogenabhängige Tumoren, Lebererkrankungen, Schwangerschaft"},
  {"id":118,"cat":"Endokrinologie / Hormone","q":"Was ist das prämature Ovarialinsuffizienz und welche Laborwerte sind typisch?","a":"Ausfall der Ovarialfunktion vor dem 40. LJ; erhöhtes FSH (>25 IU/l), erhöhtes LH, erniedrigtes Östradiol, erniedrigtes AMH; Amenorrhoe; HRT bis natürliches Menopausenalter"},
  {"id":119,"cat":"Kontrazeption","q":"Was sind häufige Nebenwirkungen des Implanon?","a":"Unregelmässige Blutungen (häufigste NW), Amenorrhoe, Kopfschmerzen, Akne, Gewichtszunahme; Pearl-Index: 0,05"},
  {"id":120,"cat":"Kontrazeption","q":"Welches Gestagen enthält die Mirena?","a":"Levonorgestrel 52 mg (lokal wirksam); Wirkdauer 5–8 Jahre; Östrogen-freie Kontrazeption; geeignet beim Stillen"},
  {"id":121,"cat":"Kontrazeption","q":"Was ist das Vorgehen bei Schwangerer mit liegender IUP und sichtbarem Faden?","a":"Sofortige Entfernung der IUP wenn Faden sichtbar und SS fortgeführt werden soll; reduziert Risiko für Spätabort; wenn Faden nicht sichtbar: sonographische Kontrolle"},
  {"id":122,"cat":"Kontrazeption","q":"Welche Medikamente schwächen die Pillenwirkung ab?","a":"Enzyminduktoren: Rifampicin, Antiepileptika (Carbamazepin, Phenytoin, Topiramat), Johanniskraut; führen zu erhöhtem Hormonstoffwechsel → Kontrazeptionsversagen"},
  {"id":123,"cat":"Kontrazeption","q":"Welches Kontrazeptivum ist beim Stillen kontraindiziert?","a":"Östrogen-haltige Kombinationspräparate in den ersten 6 Wochen; erlaubt: Gestagen-Monopräparate (Mini-Pille, Implanon, Mirena), Kupfer-IUP"},
  {"id":124,"cat":"Kontrazeption","q":"Was ist die medikamentöse Abstilltherapie der Wahl?","a":"Cabergolin (Dopaminagonist); Bromocriptin wird kaum noch verwendet; Dopaminagonisten hemmen Prolaktinsekretion"},
  {"id":125,"cat":"Kontrazeption","q":"Welches Kontrazeptivum empfiehlt man einer 16-Jährigen mit Dysmenorrhoe und Hypermenorrhoe?","a":"Kombinierte orale Kontrazeption (KOK); lindert Dysmenorrhoe und Hypermenorrhoe; alternativ Levonorgestrel-IUS (off-label bei Adoleszenten)"},
  {"id":126,"cat":"Kontrazeption","q":"Was ist ein Gestagen der 3./4. Generation mit antiandrogener Wirkung?","a":"Drospirenon (antimineralcorticoid + antiandrogenisch), Dienogest, Cyproteronacetat; geeignet bei androgenem Erscheinungsbild (Akne, Hirsutismus)"},
  {"id":127,"cat":"Urologie / Beckenboden","q":"Was sind die häufigsten Inkontinenzformen?","a":"Belastungsinkontinenz: Urinverlust bei körperlicher Belastung; Dranginkontinenz: imperativer Harndrang mit Urinverlust; Mischinkontinenz; Überlaufblase: chronische Harnretention"},
  {"id":128,"cat":"Urologie / Beckenboden","q":"Was ist die operative Therapie der Belastungsinkontinenz?","a":"TVT (Tension-free Vaginal Tape) / TVT-O als Goldstandard; alternativ Kolposuspension nach Burch; Sakrokolpopexie v.a. bei Uteroprolaps"},
  {"id":129,"cat":"Urologie / Beckenboden","q":"Was ist eine vesikovaginale Fistel und wie entsteht sie?","a":"Abnorme Verbindung zwischen Blase und Vagina; Ursachen: geburtshilfliches Trauma oder iatrogen nach Hysterektomie; Symptome: ständiger unwillkürlicher Urinabgang vaginal"},
  {"id":130,"cat":"Urologie / Beckenboden","q":"Was beurteilt die Zystomanometrie?","a":"Blasenkapazität, Detrusoraktivität, Compliance; beurteilt NICHT: Lage/Verlauf der Urethra, maximalen Urethradruck"},
  {"id":131,"cat":"Urologie / Beckenboden","q":"Welche konservativen Therapien gibt es bei Dranginkontinenz?","a":"Blasentraining, Beckenbodentraining; medikamentös: Anticholinergika (Oxybutynin, Solifenacin), Mirabegron (β3-Agonist); bei Atrophie: lokales Östrogen"},
  {"id":132,"cat":"Perinatologie","q":"Was ist das Vorgehen bei erhöhter Nackenfalte (>3,5 mm) in der 12. SSW?","a":"Erweiterte Pränataldiagnostik; Angebot: NIPT als erster Schritt; bei positivem NIPT: invasive Diagnostik (CVS oder Amniozentese) zur Bestätigung"},
  {"id":133,"cat":"Perinatologie","q":"Was ist der NIPT?","a":"Analyse freier fetaler DNA aus mütterlichem Blut; Nachweis: Trisomie 21, 18, 13, Geschlechtschromosomenstörungen; Screeningtest – auffälliges Ergebnis muss invasiv bestätigt werden"},
  {"id":134,"cat":"Perinatologie","q":"Was ist eine Chorionzottenbiopsie?","a":"Invasive Pränataldiagnostik: Entnahme von Chorionzottengewebe ab 11. SSW; Karyotypisierung; Abortrisiko ca. 0,5–1%; Vorteil: früher als Amniozentese möglich"},
  {"id":135,"cat":"Perinatologie","q":"Was bedeutet AFP-Erhöhung im mütterlichen Blut?","a":"AFP erhöht bei: Neuralrohrdefekten, Omphalozele, Gastroschisis, IUFT, Mehrlingsschwangerschaft; NICHT bei Plazentainsuffizienz allein"},
  {"id":136,"cat":"Perinatologie","q":"Was sind Fehlbildungen assoziiert mit fetalem Alkoholsyndrom?","a":"Mikrozephalie, Herzanomalien (VSD), Gesichtsdysmorphien (kurze Lidspalten, fehlendes Philtrum, schmale Oberlippe), Wachstumsretardierung, kognitive Beeinträchtigungen"},
  {"id":137,"cat":"Perinatologie","q":"Was sind typische Komplikationen bei Neugeborenen von Müttern mit Gestationsdiabetes?","a":"Makrosomie, neonatale Hypoglykämie, Polyzythämie, Hyperbilirubinämie, Atemnotsyndrom; NICHT: neonatale Hyperglykämie"},
  {"id":138,"cat":"Perinatologie","q":"Was ist eine Lippen-Kiefer-Gaumenspalte und welche Assoziationen bestehen?","a":"Häufige Fehlbildung; assoziiert mit: Polyhydramnion (Schluckstörung), Trisomie 13/18; NICHT typisch: CMV, maternale Hypothyreose"},
  {"id":139,"cat":"Perinatologie","q":"Was sind Medikamente, die in der Schwangerschaft kontraindiziert sind?","a":"ACE-Hemmer/AT1-Antagonisten, Cumarinderivate (1. Trimester: Fehlbildungen), Methotrexat, Isotretinoin, Tetracycline, Aminoglykoside; erlaubt: Penicillin, Cephalosporine, Paracetamol"},
  {"id":140,"cat":"Perinatologie","q":"Was ist die neonatale Alloimmunthrombozytopenie (NAIT)?","a":"Mutter HPA-1-negativ, Vater HPA-1-positiv; Mutter bildet Anti-HPA-1-Antikörper; fetale Thrombozytopenie, intrakranielle Blutungen; Therapie: IVIG, Thrombozytenkonzentrate"},
  {"id":141,"cat":"Perinatologie","q":"Was sind Zeichen einer fetalen Makrosomie?","a":"Fetales Gewicht >4000 g; Risiko für Schulterdystokie, Geburtstrauma, neonatale Hypoglykämie; Ursachen: Gestationsdiabetes, Adipositas, Postterminität"},
  {"id":142,"cat":"Perinatologie","q":"Was ist der Unterschied zwischen Amnionitis und Chorioamnionitis?","a":"Chorioamnionitis: bakterielle Infektion der Eihäute; Symptome: mütterliches Fieber, maternale/fetale Tachykardie, uterine Druckdolenz, übelriechende Amnionflüssigkeit; Therapie: sofortige Antibiotika und Entbindung"},
  {"id":143,"cat":"Perinatologie","q":"Wie wird Gestationsdiabetes diagnostiziert?","a":"Screening: 50g GCT 24.–28. SSW; bei auffälligem Wert: 75g oGTT; Grenzwerte: nüchtern ≥5,1 mmol/l, 1h ≥10 mmol/l, 2h ≥8,5 mmol/l"},
  {"id":144,"cat":"Onkologie","q":"Was ist die Indikation zur Trachelektomie?","a":"Zervixkarzinom Stadium IB1 bei Kinderwunsch; Erhalt des Uterus möglich; Lymphknotendissektion zusätzlich; bei IB2 oder Parametrienbefall: Radiochemotherapie bevorzugt"},
  {"id":145,"cat":"Gynäkologie","q":"Was ist Metrorragie und wann ist sie abklärungsbedürftig?","a":"Azyklische Uterusblutung; immer abklärungsbedürftig postmenopausal (Endometriumkarzinom ausschliessen); prämenopausal: Polyp, Myom, Karzinom, Gerinnungsstörung; Diagnostik: TV-Sonographie + Hysteroskopie"},
  {"id":146,"cat":"Kontrazeption","q":"Was sind Vor- und Nachteile der Kupfer-Spirale?","a":"Vorteile: hormonfreie Kontrazeption, Wirkdauer 5–10 Jahre, geeignet bei Stillzeit; Nachteile: stärkere Menstruation und Dysmenorrhoe; kein Schutz vor STI; Pearl-Index 0,6–0,8"},
  {"id":147,"cat":"Geburtshilfe","q":"Was ist das Vorgehen bei einer 29-SSW-Patientin mit pathologischem CTG und Verdacht auf fetale Azidose?","a":"Subpartale Fetalblutanalyse (pH-Messung aus Kopfhaut) zur Bestätigung; bei pH <7,20: sofortige Entbindung; biophysikalisches Profil als Alternative"},
  {"id":148,"cat":"Gynäkologie","q":"Was ist eine Endometritis und wie wird sie therapiert?","a":"Entzündung des Endometriums; häufig postpartal oder post-interventionell; Symptome: Fieber, Unterbauchschmerzen, übelriechender Ausfluss; Therapie: Antibiotika (z.B. Amoxicillin/Clavulansäure + Doxycyclin)"},
  {"id":149,"cat":"Reproduktionsmedizin","q":"Was ist das Turner-Syndrom und welche Symptome hat es?","a":"Karyotyp 45,X0; primäre Amenorrhoe, Kleinwuchs, Pterygium colli, Schildthorax, Aortenisthmusstenose, primäre Ovarialinsuffizienz; Therapie: Wachstumshormon, HRT ab Pubertät"},
  {"id":150,"cat":"Geburtshilfe","q":"Was ist die Indikation zur Anti-D-Prophylaxe in der Schwangerschaft?","a":"Rh-negative Mutter: routinemässig in der 28./34. SSW; nach invasiver Diagnostik (Amniozentese, CVS), nach Trauma, nach Abort; verhindert Rh-Alloimmunisierung"},
  {"id":151,"cat":"Infektionen / STI","q":"Was ist Chorioamnionitis und wie wird sie behandelt?","a":"Bakterielle Infektion der Eihäute; Symptome: mütterliches Fieber, maternale/fetale Tachykardie, übelriechende Amnionflüssigkeit; Therapie: sofortige Antibiotika (Ampicillin + Gentamicin) und Entbindung"},
  {"id":152,"cat":"Geburtshilfe","q":"Was ist eine Schulterdystokie und wie wird sie behandelt?","a":"Einklemmen der vorderen Schulter hinter der Symphyse nach Geburt des Kopfes; Notfall! Massnahmen: McRoberts-Manöver (Oberschenkel an Bauch), suprasymphysärer Druck, Rubin-II/Woods-Manöver, Episiotomie"},
  {"id":153,"cat":"Reproduktionsmedizin","q":"Was ist ein Hodentumor und wie beeinflusst er die Fertilität?","a":"Häufigster Tumor des jungen Mannes; vor Chemotherapie: Kryokonservierung von Spermien empfehlen; nach Chemotherapie oft Oligospermie/Azoospermie; ICSI nach Spermienzuwachs möglich"},
  {"id":154,"cat":"Infektionen / STI","q":"Welche Keime verursachen eine bakterielle Vaginose?","a":"Polymikrobiell: Gardnerella vaginalis als Leitorganismus + Anaerobier (Mobiluncus, Prevotella, Bacteroides); Therapie: Metronidazol oral oder vaginal; Clindamycin als Alternative"},
  {"id":155,"cat":"Endokrinologie / Hormone","q":"Was ist das Vorgehen bei einer Patientin mit Hirsutismus und Oligomenorrhoe?","a":"Ausschluss: AGS (17-OH-Progesteron), Nebennierenrindentumor (DHEAS, Testosteron), Cushingsyndrom (Cortisol), Hypothyreose; Häufigste Ursache: PCOS → Rotterdam-Kriterien prüfen"},
  {"id":156,"cat":"Geburtshilfe","q":"Was ist der Unterschied zwischen Abort und Fehlgeburt nach FIGO-Definition?","a":"Abort = spontaner oder induzierter Schwangerschaftsverlust <22+0 SSW oder <500g Geburtsgewicht; Frühgeburt: 22+0–36+6 SSW; Spätabort: 15.–21. SSW; Missed abortion: abgestorbene SS ohne Austreibung"},
  {"id":157,"cat":"Gynäkologie","q":"Was sind Kriterien für eine EUG (ektope Schwangerschaft)?","a":"Beta-HCG positiv, leerer Uterus im TV-Sono, Nachweis einer Adnexraumforderung oder Hämatoperitoneum; Diskriminanzgrenze: bei Beta-HCG >1500–2000 IU/l sollte intrauterine SS sichtbar sein"},
  {"id":158,"cat":"Geburtshilfe","q":"Was ist ein Bishop-Score und wofür wird er verwendet?","a":"Beurteilung der Zervixreife vor Geburtseinleitung: Muttermundseröffnung, Verkürzung, Konsistenz, Lage der Zervix, Höhe des vorangehenden Teils; Score ≥8: reife Zervix, Einleitung erfolgversprechend; Score <6: Zervixreifung (z.B. mit Prostaglandinen) empfohlen"},
  {"id":159,"cat":"Geburtshilfe","q":"Was sind die häufigsten Indikationen zur Geburtseinleitung?","a":"Übertragung (>41+0 SSW), Gestationsdiabetes mit Insulintherapie (38+0 SSW), Präeklampsie, vorzeitiger Blasensprung am Termin, IUGR mit pathologischen Dopplerindizes, Rhesusinkompatibilität, mütterliche Erkrankungen"},
  {"id":160,"cat":"Geburtshilfe","q":"Was ist der Unterschied zwischen primärer und sekundärer Sectio?","a":"Primäre (elektive) Sectio: vor Geburtsbeginn geplant; sekundäre Sectio: nach Beginn der Geburt (bei Geburtstillstand, pathologischem CTG, Missverhältnis); Notsectio: sofortige Entbindung bei akuter Gefährdung von Mutter/Kind"},
  {"id":161,"cat":"Geburtshilfe","q":"Was ist eine Plazenta praevia und welche Typen gibt es?","a":"Tiefliegende Plazenta über oder nahe dem inneren Muttermund; Typen: marginalis (reicht an den MM heran), partialis (bedeckt MM teilweise), totalis (bedeckt MM vollständig); Symptom: schmerzlose Blutung im 3. Trimester; Therapie: elektive Sectio"},
  {"id":162,"cat":"Geburtshilfe","q":"Was ist der Unterschied zwischen vorzeitiger Plazentalösung und Plazenta praevia?","a":"Vorzeitige Plazentalösung: schmerzhafte Blutung (Brettbauch), normositz Plazenta löst sich vorzeitig; Plazenta praevia: schmerzlose Blutung, Plazenta liegt tief/über MM; beide Formen können zu fetaler Notfallsituation führen"},
  {"id":163,"cat":"Geburtshilfe","q":"Was versteht man unter einem Amnioinfusionsverfahren und wann wird es eingesetzt?","a":"Instillation von steriler NaCl-Lösung in die Amnionhöhle; Indikationen: Nabelschnurkompression mit variablen Dezelerationen, Mekoniumaspiration (Verdünnung), schwere Oligohydramnie; verbessert CTG-Muster"},
  {"id":164,"cat":"Geburtshilfe","q":"Was ist eine vaginale Beckenendlagengeburt und welche Voraussetzungen gelten?","a":"Spontangeburt aus BEL möglich bei: Einling, reife SS, Frühgeburt ausgeschlossen, normale Kopfgrösse (kein Hydrozephalus), keine anderen Sectio-Indikationen, erfahrenes Team; häufige Praxis: elektive Sectio bei BEL am Termin"},
  {"id":165,"cat":"Geburtshilfe","q":"Was ist eine äussere Wendung (ECV) und wann wird sie durchgeführt?","a":"Externe Zephalische Version: äussere manuelle Wendung des Fetus aus BEL in Schädellage; ab 36+0 SSW; Erfolgsrate ~50%; Voraussetzungen: ausreichend Fruchtwasser, kein Uterusmyom, keine Plazentalösung; Komplikationen: Bradykardie, Notfallsectio"},
  {"id":166,"cat":"Geburtshilfe","q":"Was sind Zeichen eines drohenden Uterusruptur?","a":"Rissförmige Schmerzen über der Narbe, pathologisches CTG (fetale Bradykardie), aufgehörte Wehen, tastbares Band (Bandl-Furche), tastbares Kind extrauterin; Therapie: sofortige Laparotomie"},
  {"id":167,"cat":"Geburtshilfe","q":"Was ist die Bandl-Furche und was bedeutet sie?","a":"Sichtbare/tastbare Einschnürung zwischen Ober- und Unterleib beim Uterus bei drohender Uterusruptur (Retraktionsring); Zeichen für pathologische Überdehnung des Uterussegments → sofortige Sectio"},
  {"id":168,"cat":"Geburtshilfe","q":"Was ist das Vorgehen bei einem vorzeitigen Blasensprung (PROM) am Termin?","a":"Erwartungsmanagement: Geburt beginnt meist spontan innerhalb 24h; nach 12–24h ohne Geburtsbeginn: Einleitung (Oxytocin); GBS-Prophylaxe wenn GBS-positiv oder Status unbekannt; CTG-Überwachung"},
  {"id":169,"cat":"Geburtshilfe","q":"Was ist PPROM (preterm premature rupture of membranes) und wie wird es behandelt?","a":"Vorzeitiger Blasensprung vor der 37. SSW; Behandlung: antibiotische Prophylaxe (Ampicillin + Erythromycin), Lungenreifung (wenn <34. SSW), Magnesium zur Neuroprotektion (wenn <32. SSW), Überwachung auf Infektzeichen"},
  {"id":170,"cat":"Geburtshilfe","q":"Was ist ein Dammriss und welche Grade gibt es?","a":"Grad I: nur Schleimhaut; Grad II: Schleimhaut + Dammmuskulatur; Grad III: Anteile des Sphincter ani externus betroffen (IIIa <50%, IIIb >50%, IIIc vollständig); Grad IV: Rektumschleimhaut betroffen; Grad III/IV: operative Versorgung im Operationssaal"},
  {"id":171,"cat":"Geburtshilfe","q":"Was ist eine Episiotomie und wann ist sie indiziert?","a":"Erweiterungsschnitt des Damms; keine Routineindikation mehr; Indikationen: drohender schwerer Dammriss (Grad III/IV), Schulterdystokie, operative Entbindung (Forceps/Vakuum), fetale Bradykardie mit dringendem Entbindungsbedarf"},
  {"id":172,"cat":"Geburtshilfe","q":"Was ist ein Forceps und wann wird er eingesetzt?","a":"Zange zur operativen vaginalen Entbindung; Indikationen: erschöpfte Mutter, fetaler Distress im Austreibungsperiode, maternale Kontraindikation zum Pressen; Voraussetzungen: MM vollständig, Kopf eingetreten, Schädellage, Amnionhöhle eröffnet"},
  {"id":173,"cat":"Geburtshilfe","q":"Was ist der Unterschied zwischen Frühgeburt und Spätabort?","a":"Spätabort: 15.–21+6 SSW (<500g, nicht lebensfähig); Frühgeburt: 22+0–36+6 SSW (Lebensfähigkeit ab 22–24. SSW); Spätfrühgeburt: 34+0–36+6 SSW (late preterm); extreme Frühgeburt: <28. SSW"},
  {"id":174,"cat":"Geburtshilfe","q":"Was ist Oxytocin und wie wird es in der Geburtshilfe eingesetzt?","a":"Synthetisches Neuropeptid; Wehenauslösung/-verstärkung (i.v.-Infusion); postpartale Uterotonikum der ersten Wahl (10 IE i.m. oder 5 IE langsam i.v. nach Plazentageburt); Carbetocin: lang wirksames Oxytocin-Analogon bei Sectio"},
  {"id":175,"cat":"Geburtshilfe","q":"Was ist eine Inversio uteri und wie wird sie behandelt?","a":"Umstülpung des Uterusfundus durch den Zervikalkanal; Notfall; Symptome: massiver Blutverlust, Schock, sichtbare/tastbare Uterusmasse vaginal; Therapie: sofortige manuelle Reposition unter Tokolyse (Nitroglycerin, Terbutalin)"},
  {"id":176,"cat":"Geburtshilfe","q":"Was ist eine Nabelschnurvorfall und wie wird er behandelt?","a":"Prolaps der Nabelschnur vor dem vorangehenden Kindsteil nach Blasensprung; Notfall; Symptome: pathologisches CTG (Bradykardie); Therapie: sofortige Entlastung (manuell, Kopftieflage), sofortige Sectio"},
  {"id":177,"cat":"Geburtshilfe","q":"Was ist der Apgar-Score und wann wird er erhoben?","a":"Beurteilung des Neugeborenen nach 1, 5, 10 Minuten; 5 Kriterien: Herzfrequenz, Atmung, Muskeltonus, Reflexe, Hautfarbe; je 0–2 Punkte; Summe 7–10: gut; 4–6: mittel; 0–3: kritisch; Reanimation unabhängig vom Score"},
  {"id":178,"cat":"Geburtshilfe","q":"Was ist der Unterschied zwischen Laktationsamenorrhoe und sekundärer Amenorrhoe?","a":"Laktationsamenorrhoe: physiologisch durch erhöhtes Prolaktin → GnRH-Suppression; Schutz vor Schwangerschaft (LAM-Methode) nur bei vollständigem Stillen, Amenorrhoe <6 Monate postpartal; sekundäre Amenorrhoe: weitere Ursachen immer ausschliessen"},
  {"id":179,"cat":"Geburtshilfe","q":"Was sind Ursachen einer erhöhten perinatalen Mortalität bei Zwillingsschwangerschaften?","a":"Frühgeburtlichkeit, IUGR, TTTS bei monochoralen Zwillingen, Fehlbildungen, Nabelschnurumschlingung, Entbindungskomplikationen (zweiter Zwilling), plazentare Insuffizienz"},
  {"id":180,"cat":"Geburtshilfe","q":"Was ist eine Cerclage und wann wird sie durchgeführt?","a":"Chirurgische Naht um den Gebärmutterhals zur Verstärkung der Zervix; Indikationen: Zervixinsuffizienz (Zervixlänge <25 mm + Anamnese von Spätaborten), anatomische Zervixdefekte; McDonald- oder Shirodkar-Naht; Entfernung 36–37 SSW"},
  {"id":181,"cat":"Geburtshilfe","q":"Was ist Thromboprophylaxe in der Schwangerschaft und wann ist sie indiziert?","a":"Niedermolekulares Heparin (NMH) s.c.; Indikationen: Thrombose/Embolie in der Anamnese, Thrombophilie, Immobilisation, Adipositas BMI >30 + weitere Risikofaktoren; Wochenbett: mindestens 6 Wochen postpartal bei erhöhtem Risiko"},
  {"id":182,"cat":"Geburtshilfe","q":"Was ist ein Hydrops fetalis und welche Ursachen gibt es?","a":"Pathologische Flüssigkeitsansammlung in fetalen Kompartimenten (Haut, Pleura, Perikard, Aszites); Ursachen: immunologisch (Rh-Inkompatibilität), nicht-immunologisch (fetale Anämie, Herzfehler, Infektionen, Chromosomenanomalie)"},
  {"id":183,"cat":"Geburtshilfe","q":"Welche Laborwerte werden beim Ersttrimesterscreening bestimmt?","a":"PAPP-A (Pregnancy-associated plasma protein A) und freies β-HCG; kombiniert mit Nackentransparenzmessung und Alter der Mutter; Berechnung des Trisomie-21/18/13-Risikos; 1.–Trimester-Test"},
  {"id":184,"cat":"Gynäkologie","q":"Was ist die Bedeutung des Zervix-HPV-Tests in der Krebsvorsorge?","a":"HPV (Humane Papillomviren) Typ 16 und 18 verursachen >70% der Zervixkarzinome; Ko-Test (PAP + HPV): erhöhte Sensitivität; alleiniger hrHPV-Test ab 30 J empfohlen; negative HPV-Test erlaubt verlängertes Screening-Intervall (5 Jahre)"},
  {"id":185,"cat":"Gynäkologie","q":"Was sind die häufigsten HPV-Typen und welche verursachen was?","a":"Low-risk: HPV 6, 11 → Condylomata acuminata (Feigwarzen); High-risk: HPV 16, 18 → Zervixkarzinom, Vulva-/Vagina-/Analkarzinom, oropharyngeale Karzinome; HPV-Impfung schützt gegen Typen 6, 11, 16, 18 (quadrivalent) oder 9 Typen (nonavalent)"},
  {"id":186,"cat":"Gynäkologie","q":"Wann und wie wird die HPV-Impfung empfohlen?","a":"Empfohlen für Mädchen und Jungen 11–14 Jahre (2-Dosen-Schema); 15–26 Jahre: 3-Dosen-Schema; beste Wirkung vor erstem Geschlechtsverkehr; in der Schweiz empfohlen und z.T. von Kantonen übernommen"},
  {"id":187,"cat":"Gynäkologie","q":"Was ist eine Kolpitis und welche häufigen Erreger gibt es?","a":"Entzündung der Vaginalschleimhaut; Erreger: Candida albicans (weisslicher krümeliger Ausfluss, Juckreiz), Trichomonaden (schaumig-grüner Ausfluss), Gardnerella/BV (fischiger Geruch), Gonokokken/Chlamydien (Zervizitis)"},
  {"id":188,"cat":"Gynäkologie","q":"Was ist eine Douglasitis und wie entsteht sie?","a":"Entzündung im Douglas-Raum (Recto-uteriner Raum) durch absteigende Genitalinfektion oder Appendizitis; Symptome: tiefe Rektumschmerzen, Tenesmen, Druckschmerz bei rektaler Untersuchung; Abszess möglich"},
  {"id":189,"cat":"Gynäkologie","q":"Was ist ein Uterusmyom und wie wird es klassifiziert?","a":"Benigner glattmuskulärer Tumor; subserös (unter Serosa), intramural (im Myometrium), submukös (in Richtung Cavum); Symptome je nach Lage: Hypermenorrhoe (submukös), Druckgefühl, Infertilität; submukös: operative HSK-Resektion"},
  {"id":190,"cat":"Gynäkologie","q":"Was ist das Vorgehen bei einem submukösen Myom mit Hypermenorrhoe und Hb 9,5 g/dl?","a":"Operative Hysteroskopie mit Myomresektion; GnRH-Analoga zur Vorbehandlung (Volumenreduktion); alternativ bei erfülltem Kinderwunsch: myomerhaltende Myomektomie; Hysterektomie bei abgeschlossenem Kinderwunsch"},
  {"id":191,"cat":"Gynäkologie","q":"Was ist der Unterschied zwischen Dysmenorrhoe und Mittelschmerz?","a":"Dysmenorrhoe: Regelschmerzen (primär: funktionell/idiopathisch; sekundär: Endometriose, Myom, Polyp); Mittelschmerz: periovulatorischer Schmerz durch Follikelruptur, kurz, einseitig, kein Ausfluss; nicht therapiebedürftig"},
  {"id":192,"cat":"Gynäkologie","q":"Was ist ein Polyp und wie wird er diagnostiziert?","a":"Gutartige gestielte oder breitbasige Schleimhautwucherung (Endometrium- oder Zervixpolyp); Symptome: Zwischen-/Kontaktblutungen, Hypermenorrhoe; Diagnose: TV-Sonographie, Hysteroskopie; Therapie: hysteroskopische Resektion mit Histologie"},
  {"id":193,"cat":"Gynäkologie","q":"Was ist Adenomyosis uteri?","a":"Einwachsen von Endometriumdrüsen und -stroma in das Myometrium; Symptome: Dysmenorrhoe, Hypermenorrhoe, vergrösserter knotiger Uterus; Diagnose: TV-Sono (inhomogenes Myometrium), MRI; Therapie: GnRH-Analoga, Mirena, Hysterektomie"},
  {"id":194,"cat":"Gynäkologie","q":"Was ist der Unterschied zwischen primärer und sekundärer Dysmenorrhoe?","a":"Primär: keine organische Ursache, durch Prostaglandine; meist junge Frauen, Beginn mit Menarche; Therapie: NSAID, KOK; Sekundär: organische Ursache (Endometriose, Myom, Polyp, IUP); Therapie der Grunderkrankung"},
  {"id":195,"cat":"Gynäkologie","q":"Was ist ein Douglas-Abszess und wie wird er diagnostiziert und behandelt?","a":"Eiteransammlung im Recto-uterinen Raum; Symptome: Fieber, tiefe Unterbauchschmerzen, Tenesmen; Diagnose: TV-Sono (echoarme Raumforderung hinter Uterus); Therapie: transvaginale oder laparoskopische Drainage + Antibiotika"},
  {"id":196,"cat":"Gynäkologie","q":"Was ist eine Ovarialtorsion und welche Bildgebung hilft?","a":"Drehung des Ovars um seinen Gefässstiel; Symptome: plötzlicher starker einseitiger Schmerz, Übelkeit, Erbrechen; Doppler: kein/reduzierter Blutfluss (aber normaler Doppler schliesst Torsion nicht aus!); Therapie: sofortige operative Detorsion, Oophoropexie wenn möglich"},
  {"id":197,"cat":"Gynäkologie","q":"Was ist die Bartholinitis und wie wird sie von einer Bartholin-Zyste unterschieden?","a":"Bartholinitis: akute Entzündung/Abszess der Bartholin-Drüse; Bartholinzyste: obstruktive Zyste ohne Entzündung; Symptome Bartholinitis: Rötung, Schwellung, Schmerzen labial; Therapie: Marsupialisierung (beide), Antibiotika bei Abszess"},
  {"id":198,"cat":"Gynäkologie","q":"Was ist ein Vulvaödem und welche Ursachen gibt es?","a":"Schwellung der Vulva; Ursachen: allergische Reaktion (Kontaktdermatitis), Infektion (Herpes, Bartholinitis), Lymphödem, Hämatom, Varizen; Abklärung: Nativpräparat, Abstrich, Inspektion"},
  {"id":199,"cat":"Gynäkologie","q":"Was ist der extrauterine Schwangerschafts-Sonderfall «Ovarialgravidität»?","a":"Nidation der befruchteten Eizelle im Ovar; sehr selten (<3% aller EUG); Risikofaktor: IUP (Kupferspirale schützt vor intrauteriner, aber nicht ovarieller Gravidität); Therapie: operative Entfernung, selten Methotrexat"},
  {"id":200,"cat":"Gynäkologie","q":"Was ist eine Zervizitis und welche Erreger sind häufig?","a":"Entzündung der Zervix; häufige Erreger: Chlamydien, Gonokokken, HSV, Trichomonaden; Symptome: mukopurulenter Ausfluss, Kontaktblutungen, Portioschiebeschmerz; Therapie: erregerspezifisch, immer Partnerbehandlung"},
  {"id":201,"cat":"Gynäkologie","q":"Was ist ein Pyometra?","a":"Eiteransammlung in der Uterushöhle; häufig bei postmenopausalen Frauen mit Zervixstenose; Symptome: Unterbauchschmerzen, Fieber, eitriger Ausfluss; Diagnose: Sono (hydrometer-ähnlich); Therapie: Zervix-Dilatation + Drainage + Antibiotika + Ausschluss Karzinom"},
  {"id":202,"cat":"Gynäkologie","q":"Was versteht man unter Dysplasie und dem PAP-System?","a":"PAP I/II: keine/geringe Auffälligkeiten; PAP IIw: Wiederholung in 3–6 Monaten; PAP III: unklare Befunde; PAP IIID: CIN I/II (leichte bis mittlere Dysplasie); PAP IVa/IVb: CIN III/Carcinoma in situ; PAP V: invasives Karzinom"},
  {"id":203,"cat":"Gynäkologie","q":"Was ist der Unterschied zwischen CIN I, II und III?","a":"CIN I (leichte Dysplasie): unteres Drittel des Epithels; CIN II (mittlere): untere zwei Drittel; CIN III (schwere Dysplasie/Carcinoma in situ): gesamte Epitheldicke betroffen; CIN I: meist Regression; CIN III: Konisation indiziert"},
  {"id":204,"cat":"Gynäkologie","q":"Was ist ein Hämato-/Hydrokolpos?","a":"Blut- (Hämatokolpos) oder Flüssigkeitsansammlung (Hydrokolpos) in der Vagina; Ursachen: Hymenalatresie, Scheidenseptum; Symptome: primäre Amenorrhoe, zyklische Schmerzen, Harnverhalt; Therapie: operative Eröffnung"},
  {"id":205,"cat":"Gynäkologie","q":"Was versteht man unter einem Scheidenpessar und wann wird es eingesetzt?","a":"Silikonring oder Würfelform in der Vagina zur Unterstützung von Uterus/Blase; Indikationen: Deszensus, Inkontinenz; nicht-operative Alternative; regelmässige Kontrollen und Reinigung nötig; keine Dauerlösung bei jungen Patientinnen"},
  {"id":206,"cat":"Gynäkologie","q":"Was ist eine Retroflexio uteri und ist sie pathologisch?","a":"Rückwärtsneigung des Uterus; in 20% der Frauen normal (Normvariante); meist asymptomatisch; kann Dyspareunie verursachen; pathologisch bei fixierter Retroflexio durch Endometriose oder Entzündung"},
  {"id":207,"cat":"Gynäkologie","q":"Was ist das Prinzip der Kolposkopie?","a":"Vergrösserung der Zervix unter Weissessiganwendung (3–5% Essigsäure) und Lugol'scher Lösung (Jodprobe); acetoweisse Areale: Dysplasie-verdächtig; Jodnegativität: gestörte Glykogenspeicherung (CIN, Karzinom); gezielte Biopsie"},
  {"id":208,"cat":"Onkologie","q":"Was ist das Lynch-Syndrom und welche Tumoren sind assoziiert?","a":"Hereditäres nichtpolypöses kolorektales Karzinom (HNPCC); Mutationen in Mismatch-Repair-Genen (MLH1, MSH2, MSH6, PMS2); erhöhtes Risiko: Kolorektal-, Endometrium-, Ovarial-, Magen-, Urothel-Karzinome; Screening: jährlich Koloskopie + gynäkologische Vorsorge"},
  {"id":209,"cat":"Onkologie","q":"Was ist das BRCA1/2-Syndrom und welche Optionen hat die Patientin?","a":"Keimbahnmutationen in BRCA1 oder BRCA2; BRCA1: 70% Lebensrisiko Mamma-Ca, 40% Ovarial-Ca; BRCA2: 70% Mamma-Ca, 20% Ovarial-Ca; Optionen: intensiviertes Screening (MRI), prophylaktische Mastektomie/Salpingo-Oophorektomie, Chemopravention (Tamoxifen)"},
  {"id":210,"cat":"Onkologie","q":"Was ist triple-negatives Mammakarzinom?","a":"ER-negativ, PR-negativ, Her2-negativ; aggressiver Subtyp; häufiger bei jungen Frauen, BRCA1-Mutationsträgerinnen; keine Endokritherapie oder Trastuzumab möglich; Chemotherapie ist Hauptpfeiler; schlechtere Prognose"},
  {"id":211,"cat":"Onkologie","q":"Was ist Her2-positives Mammakarzinom und wie wird es behandelt?","a":"Überexpression des HER2-Rezeptors (Amplifikation des HER2-Gens); Therapie: Chemotherapie + Trastuzumab (Herceptin) ± Pertuzumab; adjuvant T-DM1 (Kadcyla) nach neoadjuvanter Therapie mit Restbefund; bessere Prognose als früher"},
  {"id":212,"cat":"Onkologie","q":"Was ist die TNM-Klassifikation beim Mammakarzinom?","a":"T: Tumorgrösse (T1: ≤2cm, T2: 2–5cm, T3: >5cm, T4: Haut-/Brustwandinfiltration); N: Lymphknoten (N0: kein Befall, N1–3: regionale LK); M: Fernmetastasen (M0/M1); Staging bestimmt Therapie und Prognose"},
  {"id":213,"cat":"Onkologie","q":"Was ist inflammatorisches Mammakarzinom?","a":"Seltener, aggressiver Subtyp; Symptome: diffuse Rötung, Schwellung, Wärme, Peau d'orange (Lymphangiosis carcinomatosa); kein palpierter Tumor; Diagnose: Hautbiopsie + Bildgebung; Therapie: neoadjuvante Chemotherapie, danach Op + RT"},
  {"id":214,"cat":"Onkologie","q":"Was ist der Sentinel-Lymphknoten-Biopsy (SLNB) beim Mammakarzinom?","a":"Entnahme des ersten Lymphknotens im Abflussgebiet (Sentinel-LK) mittels Technetium-Szintigraphie ± Farbstoff; wenn Sentinel negativ: keine axilläre Lymphadenektomie nötig; reduziert Lymphödemrisiko"},
  {"id":215,"cat":"Onkologie","q":"Was ist das Ovarial-Ca FIGO-Stadium und welche Histologien gibt es?","a":"FIGO I: auf Ovar begrenzt; II: Beckenausdehnung; III: Peritoneum/LK-Metastasen; IV: Fernmetastasen; Histologien: serös high-grade (häufigste, schlechteste Prognose), endometrioid, klarzellig, muzinös; BRCA-Mutation: high-grade serös häufiger"},
  {"id":216,"cat":"Onkologie","q":"Was ist PARP-Inhibitor-Therapie beim Ovarialkarzinom?","a":"Poly-ADP-Ribose-Polymerase-Inhibitoren (Olaparib, Niraparib); wirken bei BRCA-Mutation durch synthetische Letalität; adjuvante Erhaltungstherapie nach Platin-basierter Chemo beim high-grade serösen Ovarialkarzinom; verbessert progressionsfreies Überleben"},
  {"id":217,"cat":"Onkologie","q":"Was ist Bevacizumab und wann wird es beim Ovarialkarzinom eingesetzt?","a":"Anti-VEGF-Antikörper (Anti-Angiogenese); kombiniert mit Carboplatin/Paclitaxel beim fortgeschrittenen Ovarialkarzinom (FIGO III/IV); Erhaltungstherapie nach Chemotherapie; Nebenwirkungen: Hypertonie, Thrombose, Wundheilungsstörungen"},
  {"id":218,"cat":"Onkologie","q":"Was ist das Endometriumkarzinom Typ I vs. Typ II?","a":"Typ I: östrogenabhängig, endometrioid, gut differenziert (G1/G2), bessere Prognose, meist FIGO I/II; Typ II: östrogenunabhängig, nicht-endometrioid (serös, klarzellig), schlecht differenziert, schlechtere Prognose"},
  {"id":219,"cat":"Onkologie","q":"Was sind Risikofaktoren für das Endometriumkarzinom?","a":"Östrogenexzess: Adipositas, Nulliparität, späte Menopause, Tamoxifen, PCO-Syndrom, Hormonersatztherapie (Östrogen ohne Gestagen); Schutzfaktor: KOK, Schwangerschaft, körperliche Aktivität"},
  {"id":220,"cat":"Onkologie","q":"Was ist ein Leiomyosarkom?","a":"Seltener maligner glattmuskulärer Tumor des Uterus; meist postmenopausal; Symptome: Blutung, schnell wachsende Uterusmasse; schlechte Prognose; präoperativ schwer von Myom zu unterscheiden (MRI hilfreich); Therapie: Hysterektomie"},
  {"id":221,"cat":"Onkologie","q":"Was ist das Krukenberg-Tumor?","a":"Ovarialmetastase (meist bilateral) eines Magenkarzinoms (seltener Kolon, Appendix, Mamma); enthält Siegelringzellen; meist jüngere Frauen; schlechte Prognose; immer Primärtumor suchen"},
  {"id":222,"cat":"Onkologie","q":"Was ist ein Granulosazelltumor des Ovars?","a":"Stromazell-Tumor; produziert Östrogen → endometriale Hyperplasie, präpubertäre Pubertas praecox oder postmenopausale Blutung; Tumormarker: Inhibin, AMH; meist FIGO I; Therapie: Operation; gute Prognose bei Stadium I"},
  {"id":223,"cat":"Onkologie","q":"Was ist die Konisation und welche Typen gibt es?","a":"Operative Entfernung eines kegelförmigen Gewebsstücks der Zervix; Indikationen: CIN III, mikroinvasives Karzinom; Typen: Messerkonisation (histologisch genaueste Ränder), LEEP/LLETZ (elektrochirurgisch), Laserkonisation; Risiko: Inkompetenz der Zervix"},
  {"id":224,"cat":"Onkologie","q":"Was sind Tumormarker in der Gynäkologie?","a":"CA-125: Ovarialkarzinom (auch bei Endometriose, Peritonitis erhöht); AFP: Keimzelltumor; HCG: Chorionkarzinom, Blasenmole; LDH: Keimzelltumor; CEA: kolorektale Metastasen; HE4: Ovarialkarzinom (spezifischer als CA-125)"},
  {"id":225,"cat":"Onkologie","q":"Was ist das ROMA-Score?","a":"Risk of Ovarian Malignancy Algorithm; kombiniert CA-125 und HE4 mit Menopausenstatus; berechnet Wahrscheinlichkeit für malignen Ovarialtumor; höherer ROMA-Score = höheres Malignitätsrisiko; bessere Spezifität als CA-125 allein"},
  {"id":226,"cat":"Onkologie","q":"Was ist die Bedeutung von Lymphknotenbefall beim Zervixkarzinom?","a":"Lymphknotenmetastasen verschlechtern Prognose deutlich; bei LK-Befall: Radiochemotherapie bevorzugt; pelvine LK befallen: häufig bei IB2 und höher; paraaortale LK: FIGO III; LK-Dissektion diagnostisch und therapeutisch"},
  {"id":227,"cat":"Onkologie","q":"Was ist Neo-Adjuvanz beim Mammakarzinom?","a":"Chemotherapie vor der Operation; Ziele: Tumorverkleinerung (BET-Ermöglichung), In-vivo-Testung der Chemosensibilität; pCR (pathologische Komplettremission) = keine Tumorzellen im Operationspräparat = beste Prognose; bei HER2+ und TNBC empfohlen"},
  {"id":228,"cat":"Reproduktionsmedizin","q":"Was ist Stimulation mit Gonadotropinen und wann wird sie eingesetzt?","a":"FSH/LH-Gabe zur Follikelreifung; Indikationen: IVF/ICSI, anovulatorische Zyklen (z.B. PCOS nach Letrozol-Versagen), hypothalamische Amenorrhoe; Monitoring: TV-Sono + Östradiol; Komplikation: Überstimulationssyndrom (OHSS)"},
  {"id":229,"cat":"Reproduktionsmedizin","q":"Was ist das OHSS (ovarielles Hyperstimulationssyndrom)?","a":"Komplikation der ovariellen Stimulation; Ovargrösse zunahme, Aszites, Pleuraerguss, Hämokonzentration, Thrombosegefahr; mild: leichte Beschwerden; schwer: Hospitalisation, i.v. Flüssigkeit, Antikoagulation; Prävention: GnRH-Agonist-Trigger, Coasting, Embryo-Kryokonservierung"},
  {"id":230,"cat":"Reproduktionsmedizin","q":"Was ist eine Insemination und wann ist sie indiziert?","a":"Instillation von aufbereitetem Sperma in Uterushöhle (IUI) oder Zervixkanal (ICI); Indikationen: leichte Oligo-/Astheno-/Teratozoospermie, Zervixfaktor (Antispermien-Ak), Samenspende; Erfolgsrate pro Zyklus ca. 10–15%; max. 3–6 Versuche"},
  {"id":231,"cat":"Reproduktionsmedizin","q":"Was ist die Hysterosalpingographie (HSG) und wann wird sie eingesetzt?","a":"Röntgendarstellung von Uterushöhle und Tuben mit Kontrastmittel; Nachweis von Tubenverschluss, Uterusfehlbildungen, Synechien; Alternative: HyCoSy (Sonohysterographie mit Kontrastmittel); laparoskopische Chromopertubation als Goldstandard"},
  {"id":232,"cat":"Reproduktionsmedizin","q":"Was ist die Laparoskopie in der Infertilitätsabklärung?","a":"Goldstandard für Nachweis von Endometriose, Adhäsionen, Tubenpatenz (Chromopertubation); Indikationen: Auffälligkeiten in HSG, Endometriose-Verdacht, unerklärte Infertilität; gleichzeitig therapeutisch möglich"},
  {"id":233,"cat":"Reproduktionsmedizin","q":"Was ist eine Kryokonservierung von Eizellen?","a":"Einfrieren von befruchteten (Pronukleusstadium) oder unbefruchteten Oozyten; Indikation: onkologische Erkrankung vor Chemo-/Radiotherapie (fertility preservation), IVF-Überschusseizellen, soziale Indikation; Vitrifizierung (Schnellgefrieren) Standard"},
  {"id":234,"cat":"Reproduktionsmedizin","q":"Was ist das adrenogenitale Syndrom (AGS) und wie wird es diagnostiziert?","a":"Autosomal-rezessiver Enzymdefekt (meist 21-Hydroxylase); erhöhte Androgene, erniedrigtes Kortisol; Neugeborenenscreening: 17-OH-Progesteron; Symptome: Virilisierung des weiblichen Genitales, Salzverlust in schwerer Form; Therapie: Glukokortikoide"},
  {"id":235,"cat":"Reproduktionsmedizin","q":"Was ist eine Spermienanalyse (Spermiogramm) und was sind die WHO-Grenzwerte?","a":"Volumen ≥1,5 ml, Konzentration ≥16 Mio./ml, Gesamtzahl ≥39 Mio., Motilität ≥42% (progressiv ≥30%), Morphologie ≥4% (Kruger); Oligo: <16 Mio.; Astheno: reduzierte Motilität; Terato: >96% abnorme Formen; Azoospermie: keine Spermien"},
  {"id":236,"cat":"Reproduktionsmedizin","q":"Was ist der Unterschied zwischen Ejakulat-Azoospermie und obstruktiver Azoospermie?","a":"Obstruktiv: normale Spermatogenese, blockierte Ausleitung (Vasektomie, Epididymitis); FSH normal; TESE positiv (Spermien im Hoden); nicht-obstruktiv: gestörte Spermatogenese (Klinefelter, Chemotherapie); FSH erhöht; TESE möglicherweise positiv"},
  {"id":237,"cat":"Reproduktionsmedizin","q":"Was ist Präimplantationsdiagnostik (PGT) und wann ist sie erlaubt?","a":"Genetische Untersuchung von Embryonen vor Transfer (IVF/ICSI); in der Schweiz erlaubt seit 2017 für Chromosomenanomalien, schwere Erbkrankheiten und strukturelle Chromosomenumlagerungen der Eltern; Geschlechtsselektion ohne medizinische Indikation verboten"},
  {"id":238,"cat":"Reproduktionsmedizin","q":"Was ist der Unterschied zwischen Subfertilität und Sterilität?","a":"Sterilität: keine Konzeption trotz regelmässigem GV über 12 Monate (primär: nie schwanger; sekundär: nach vorheriger SS); Subfertilität: reduzierte, aber nicht aufgehobene Fertilität; Infertilität: Unfähigkeit eine lebensfähige SS auszutragen"},
  {"id":239,"cat":"Infektionen / STI","q":"Was sind Zeichen und Therapie einer Syphilis in der Schwangerschaft?","a":"Primärstadium: schmerzloses Ulkus (Harter Schanker); Sekundär: Exanthem, Kondylomata lata; kongenital: Nasensattelbildung, Knochenläsionen, Organmissbildungen; Therapie: Penicillin G i.m. in allen Stadien; Partnerbehandlung obligat"},
  {"id":240,"cat":"Infektionen / STI","q":"Was ist konnatale Röteln und wie wird sie verhindert?","a":"Infektion im 1. Trimester: schwere Fehlbildungen (Herzfehler, Katarakt, Taubheit, Microzephalie = Gregg-Trias); nach 16. SSW: kaum Fehlbildungen; Prävention: Impfung (Lebendimpfstoff) vor Schwangerschaft; in SS kontraindiziert; Serostatus prüfen"},
  {"id":241,"cat":"Infektionen / STI","q":"Was ist kongenitale Toxoplasmose und wie wird sie behandelt?","a":"Übertragung nur bei Erstinfektion in der SS; typische Trias: Chorioretinitis, Hydrozephalus, intrakranielle Verkalkungen; Behandlung: Spiramycin (Übertragungsreduktion), bei fetaler Infektion: Pyrimethamin + Sulfadiazin + Folinsäure"},
  {"id":242,"cat":"Infektionen / STI","q":"Was ist Varizella-Zoster-Virus (VZV) in der Schwangerschaft?","a":"Mütterliche Infektion: schwerer Verlauf (Pneumonie); fetale Schäden: kongenitales Varizellensyndrom (Hautnarben, Gliedmassenhypoplasie, ZNS-Defekte); Gefahr besonders 13.–20. SSW; Therapie: Aciclovir; VZIG-Prophylaxe bei exponierter nicht-immuner Schwangerer"},
  {"id":243,"cat":"Infektionen / STI","q":"Was ist GBS-Screening in der Schwangerschaft?","a":"Gruppe-B-Streptokokken (Streptococcus agalactiae)-Screening durch Vaginal-/Analabstrich in der 35.–37. SSW; GBS-positiv: intrapartale Antibiotikaprophylaxe (Penicillin G i.v.); Ziel: neonatale GBS-Sepsis/Meningitis verhindern"},
  {"id":244,"cat":"Infektionen / STI","q":"Was ist eine Episiotomie-Infektion und wie wird sie therapiert?","a":"Wundinfektion der Episiotomie/Dammnaht; Symptome: Rötung, Schwellung, eitriger Ausfluss, Schmerzen; Therapie: Wundöffnung und Drainage, Wundspülungen, Antibiotika (Amoxicillin/Clavulansäure), Wundtoilette"},
  {"id":245,"cat":"Infektionen / STI","q":"Was sind die typischen Symptome einer Herpessimplexvirus (HSV)-Infektion genital?","a":"Primärinfektion: multiple schmerzhafte Bläschen/Ulzera an Vulva, Vagina, Zervix, systemisches Symptome (Fieber, Lymphknotenschwellung); Rezidiv: milderer Verlauf; Therapie: Aciclovir; Sectio bei aktiver Erstinfektion unter Geburt"},
  {"id":246,"cat":"Infektionen / STI","q":"Was ist die Bedeutung von Antiphospholipid-Antikörpern in der Schwangerschaft?","a":"Antiphospholipid-Syndrom (APS): Lupus-Antikoagulans, Anti-Cardiolipin-Ak, Anti-β2-Glykoprotein-Ak; Risiken: Thrombosen, wiederholte Fehlgeburten, IUGR, Präeklampsie, Plazentalösung; Therapie: Aspirin + NMH in der SS"},
  {"id":247,"cat":"Infektionen / STI","q":"Was ist Toxinschock-Syndrom (TSS) und wie hängt es mit gynäkologischen Erkrankungen zusammen?","a":"Durch S. aureus-Toxin TSST-1 oder Streptokokken-Toxine; assoziiert mit Tampons, Vaginalpackungen, IUP; Symptome: hohes Fieber, diffuses Erythem, Hypotonie, Multiorganversagen; Therapie: Herd-Entfernung, Antibiotika, intensivmedizinische Unterstützung"},
  {"id":248,"cat":"Infektionen / STI","q":"Was ist Mycoplasma genitalium und wie wird es behandelt?","a":"STI durch Mycoplasma genitalium; Symptome: Zervizitis, Urethritis, PID; häufig asymptomatisch; zunehmende Antibiotikaresistenz (Azithromycin); Therapie: Moxifloxacin oder Azithromycin (wenn sensibel); Partnerbehandlung; Diagnostik: PCR"},
  {"id":249,"cat":"Infektionen / STI","q":"Was ist Lymphogranuloma venereum (LGV)?","a":"STI durch Chlamydia trachomatis Serotyp L1–L3; selten in Europa, häufiger bei MSM; Symptome: schmerzloses Ulkus, Lymphknotenschwellung (Bubo), Proktitis; Therapie: Doxycyclin 100 mg 2x täglich für 21 Tage"},
  {"id":250,"cat":"Endokrinologie / Hormone","q":"Was ist eine funktionelle hypothalamische Amenorrhoe (FHA)?","a":"Suppression der GnRH-Sekretion durch Stress, Untergewicht, exzessiven Sport oder Essstörung; niedrige LH/FSH/Östradiol; kein organischer Befund; Therapie: Gewichtsnormalisierung, Stressreduktion, psychologische Unterstützung; kein primäres hormonelles Problem"},
  {"id":251,"cat":"Endokrinologie / Hormone","q":"Was ist der Menstruationszyklus und welche Hormone regulieren ihn?","a":"Follikelphase (Tag 1–14): FSH → Follikelreifung → Östradiolproduktion; Ovulation (Tag 14): LH-Peak; Lutealphase (Tag 15–28): Progesteron vom Corpus luteum; ohne Befruchtung: Corpus-luteum-Regression → Progesteronabfall → Menstruation"},
  {"id":252,"cat":"Endokrinologie / Hormone","q":"Was ist Hyperprolaktinämie und welche Symptome verursacht sie?","a":"Erhöhtes Prolaktin (>25 ng/ml); Ursachen: Prolaktinom, Hypothyreose, Medikamente (Antipsychotika, Antiemetika), Stress, Stillen; Symptome: Galaktorrhoe, Amenorrhoe/Oligomenorrhoe, Anovulation, Libidoverlust; Therapie: Dopaminagonisten (Cabergolin, Bromocriptin)"},
  {"id":253,"cat":"Endokrinologie / Hormone","q":"Was ist die Funktion von Inhibin B und AMH im weiblichen Zyklus?","a":"Inhibin B: produziert von Granulosazellen; hemmt FSH-Ausschüttung; Marker für ovarielle Reserve; AMH (Anti-Müller-Hormon): produziert von Granulosazellen kleiner Antralfollikel; zyklusunabhängig; bester Marker für ovarielle Reserve; erniedrigt bei POI, erhöht bei PCOS"},
  {"id":254,"cat":"Endokrinologie / Hormone","q":"Was ist Cushing-Syndrom und wie äussert es sich gynäkologisch?","a":"Hyperkortismus; Ursachen: Kortikosteroid-Einnahme (häufigste), Adenom der Hypophyse (Morbus Cushing), NNR-Tumor; Symptome: Stammfettsucht, Striae rubrae, Akne, Hirsutismus, Amenorrhoe, Hypertonie, Osteoporose; Diagnose: Dexamethason-Suppressionstest"},
  {"id":255,"cat":"Endokrinologie / Hormone","q":"Was ist das Klimakterium und wie unterscheidet es sich von der Menopause?","a":"Klimakterium: mehrjährige Übergangsperiode; Perimenopause: 2–3 Jahre vor letzter Menstruation; Menopause: letzte Menstruation (rückwirkend nach 12 Monaten Amenorrhoe); Postmenopause: Zeit danach; durchschnittliches Menopausenalter: 51 Jahre"},
  {"id":256,"cat":"Endokrinologie / Hormone","q":"Was ist Osteoporose und warum ist das Risiko postmenopausal erhöht?","a":"Verminderung der Knochenmasse und -qualität; postmenopausal: Östrogenmangel → erhöhte Osteoklastenaktivität → Knochenmasseverlust; Diagnose: DXA (T-Score ≤-2,5); Therapie: Kalzium + Vitamin D, Bisphosphonate, Denosumab, HRT"},
  {"id":257,"cat":"Endokrinologie / Hormone","q":"Was ist die Pubertas praecox und wann muss sie abgeklärt werden?","a":"Vorzeitige Pubertätsentwicklung: Mädchen <8 Jahre (Thelarche), Menstruation <10 Jahre; Ursachen: idiopathisch (häufig), ZNS-Tumoren, Granulosazelltumor, McCune-Albright-Syndrom; Abklärung: LH/FSH-Messung, GnRH-Stimulationstest, Knochenalter-Röntgen"},
  {"id":258,"cat":"Endokrinologie / Hormone","q":"Was ist das Swyer-Syndrom?","a":"46,XY-Gonadendysgenesie; phänotypisch weiblich (normal Vulva, Uterus vorhanden), keine Pubertätsentwicklung (keine Gonaden funktionsfähig); primäre Amenorrhoe; Gonadektomie wegen Tumorrisiko (Gonadoblastom); HRT für Pubertätsinduktion"},
  {"id":259,"cat":"Endokrinologie / Hormone","q":"Was versteht man unter dem bipolaren Temperaturprofil (basale Körpertemperatur)?","a":"Präovulatorisch: niedrige Temperatur (<36,7°C); postovulatorisch: Temperaturanstieg (>0,2°C) durch Progesteron; biphasische Kurve zeigt Ovulation; einphasig bei: anovulatorischen Zyklen, Turner-Syndrom, AIS, Menopause, Rokitansky-Syndrom; kein Marker für Zyklustag der Ovulation"},
  {"id":260,"cat":"Endokrinologie / Hormone","q":"Was ist der Luteinisierungshormon-Peak (LH-Peak) und wie wird er genutzt?","a":"LH-Surge tritt ca. 36–40 Stunden vor Ovulation auf; Nachweis im Urin (Ovulationstest) oder Blut; zur Timing der IUI oder geplanten GV; LH-Peak unterbleibt bei: Hypothalamus-/Hypophyseninsuffizienz, GnRH-Analoga-Unterdrückung, anovulatorischen Zyklen"},
  {"id":261,"cat":"Kontrazeption","q":"Was ist die «Pille danach» und wie wirkt sie?","a":"Notfallkontrazeption; Levonorgestrel (bis 72h) oder Ulipristalacetat (bis 120h) nach ungeschütztem GV; hemmt/verzögert Ovulation; wirkt NICHT als Abortivum nach Nidation; Kupfer-IUP: effektivste Notfallkontrazeption bis 5 Tage"},
  {"id":262,"cat":"Kontrazeption","q":"Was ist der Pearl-Index und was bedeutet er?","a":"Mass für die Zuverlässigkeit einer Verhütungsmethode; Anzahl Schwangerschaften pro 100 Frauenjahre; KOK: 0,1–0,9; Kondom: 2–15 (typisch); Kupfer-IUP: 0,3–0,8; keine Verhütung: 80–90; je niedriger, desto sicherer"},
  {"id":263,"cat":"Kontrazeption","q":"Was ist die Vaginal-Ring (NuvaRing) und wie wird er angewendet?","a":"Vaginaler Ring mit Östrogen (Ethinylöstradiol) + Gestagen (Etonogestrel); 21 Tage vaginal, 7 Tage Pause; systemische Wirkung durch vaginale Resorption; Vorteile: kein tägliches Einnehmen, stabile Hormonspiegel; Anwendungsfehler seltener"},
  {"id":264,"cat":"Kontrazeption","q":"Was ist das Pflasterverhütung (Evra-Pflaster) und wie wird es verwendet?","a":"Transdermales Östrogen/Gestagen-Pflaster; Wechsel wöchentlich für 3 Wochen, 1 Woche Pause; höhere Östrogenexposition als bei oraler KOK; Thromboserisiko leicht erhöht; geeignet für Frauen mit Einnahmeproblemen"},
  {"id":265,"cat":"Kontrazeption","q":"Was ist Notfallkontrazeption mit Kupfer-IUP?","a":"Kupfer-IUP-Einlage innerhalb 5 Tage nach ungeschütztem GV; effektivste Notfallkontrazeption (Versagensrate <0,1%); wirkt durch Spermienbeeinträchtigung + verhinderte Nidation; gleichzeitig langfristige Verhütung möglich"},
  {"id":266,"cat":"Kontrazeption","q":"Was ist die Laktationsamenorrhoe-Methode (LAM)?","a":"Verhütung durch vollständiges Stillen (>6x/24h), innerhalb 6 Monate postpartal, bei Amenorrhoe; Effektivität >98% wenn alle 3 Kriterien erfüllt; durch erhöhtes Prolaktin → Ovulationshemmung; bei Abweichung: zusätzliche Verhütung nötig"},
  {"id":267,"cat":"Kontrazeption","q":"Was sind Vorteile der Hormonspirale (Mirena) gegenüber KOK?","a":"Lokal wirksam (kein Östrogen); geeignet beim Stillen, bei Kontraindikationen für Östrogen (Thrombose, Migräne mit Aura), Raucherinnen >35 Jahre; reduziert Menstruation stark (bis Amenorrhoe); Einmalgabe 5–8 Jahre; hohe Compliance"},
  {"id":268,"cat":"Kontrazeption","q":"Was ist «Pill-in-the-pocket» und wann kann sie eingesetzt werden?","a":"Nicht der korrekte gynäkologische Terminus; gemeint ist oft die «Pille danach»; in der Kardiologie: Flecainid bei paroxysmalen Vorhofflimmern; gynäkologisch nicht als Standardterm gebräuchlich"},
  {"id":269,"cat":"Kontrazeption","q":"Was ist der Unterschied zwischen Minipille und KOK?","a":"Minipille (Gestagen-Monopräparat): kein Östrogen; täglich ohne Pause einnehmen; Wirkung: Zervixschleimhemmung (+ Ovulationshemmung bei höherer Dosis Desogestrel); geeignet in Stillzeit; KOK: Östrogen + Gestagen; zuverlässigere Ovulationshemmung"},
  {"id":270,"cat":"Kontrazeption","q":"Was ist die Sterilisation der Frau und welche Methoden gibt es?","a":"Tubensterilisation: laparoskopische Okklusion durch Clips (Filshie), Ringe (Falope) oder Koagulation; alternativ hysteroskopische Sterilisation (Essure – nicht mehr verfügbar); Reversibilität gering (<50% Erfolg bei Rekanalisierung); keine Hormonwirkung"},
  {"id":271,"cat":"Urologie / Beckenboden","q":"Was ist ein Urethraldivertikel und wie äussert es sich?","a":"Aussackung der Harnröhre; Symptome: Dysurie, Harnweginfektionen, Harninkontinenz, vaginale Masse; Diagnose: MRI, Urethrozystoskopie; Therapie: operative Exzision (Divertikulektomie)"},
  {"id":272,"cat":"Urologie / Beckenboden","q":"Was ist Interstitielle Zystitis (IC) und wie wird sie behandelt?","a":"Chronische Blasenentzündung ohne nachweisbaren Infekt; Symptome: Dranginkontinenz, suprapubische Schmerzen, Dyspareunie, häufiges Wasserlassen; Diagnose: Zystoskopie (Glomerulationen, Hunner-Läsion), Biopsie; Therapie: Pentosanpolysulfat, Blaseninstillationen, DMSO, Physiotherapie"},
  {"id":273,"cat":"Urologie / Beckenboden","q":"Was ist ein Rezidiv-Harnwegsinfekt und wie wird er definiert?","a":"≥2 kulturgesicherte HWI in 6 Monaten oder ≥3 in 12 Monaten; Risikofaktoren: Postmenopause (Östrogenmangel), Diabetesmellitus, IUP, anatomische Anomalien; Abklärung: Urokultur, Sono Nieren/Blase, Urethrozystoskopie; Prophylaxe: lokales Östrogen, Cranberry, niedrig dosierte Antibiotika"},
  {"id":274,"cat":"Urologie / Beckenboden","q":"Was ist eine Überlaufblase?","a":"Chronischer Harnverhalt mit Überlaufinkontinenz; Ursachen: neurogene Blase, obstruktive Uropathie, Medikamente (Anticholinergika), nach Beckenbodenchirurgie; Diagnose: Restharnmessung (>200 ml), Urodynamik; Therapie: Katheteri­sierung (ISK), Harnableitung, Ursachenbehandlung"},
  {"id":275,"cat":"Urologie / Beckenboden","q":"Was ist die Urodynamik und welche Parameter werden gemessen?","a":"Funktionsuntersuchung der Blase; Parameter: Blasenkapazität, Detrusordruck, Restharn, Urethradruckprofil, Uroflowmetrie; Indikation: unklare Inkontinenz, vor Inkontinenz-Op, Verdacht auf Detrusor-Überaktivität oder neurogene Blase"},
  {"id":276,"cat":"Urologie / Beckenboden","q":"Was ist ein Uterusprolaps und welche Grade gibt es?","a":"Deszensus des Uterus durch den Genitalhiatus; Grad I: Zervix bis vaginalem Drittel; Grad II: Zervix bis zum Hymenalsaum; Grad III: Zervix jenseits Hymenalsaum; Grad IV (Prolapso totalis): vollständige Ausstülpung; Risikofaktoren: Vaginale Geburten, Schwäche des Beckenbodens"},
  {"id":277,"cat":"Urologie / Beckenboden","q":"Was ist eine Rektozele und wie ist sie von einer Zystozele zu unterscheiden?","a":"Rektozele: Rektumwand bulgt durch hintere Vaginalwand; Symptome: Defäkationsprobleme, Gefühl der unvollständigen Entleerung, digitale Unterstützung; Zystozele: Blase/Blasenvorderwand bulgt durch vordere Vaginalwand; Miktionsprobleme, Harninkontinenz"},
  {"id":278,"cat":"Urologie / Beckenboden","q":"Was ist Sakrokolpopexie?","a":"Laparoskopische oder offene Operation zur Behandlung des Scheidenblindsackprolapses nach Hysterektomie; Aufhängung der Scheide am Promontorium/Sakrum mittels Netz; Alternative: sacrospinale Fixation nach Richter (vaginal)"},
  {"id":279,"cat":"Urologie / Beckenboden","q":"Was ist eine Detrusor-Überaktivität?","a":"Unwillkürliche Detrusorkontraktionen in der Füllungsphase; Ursache: idiopathisch oder neurogen; Symptome: Harndrang, Dranginkontinenz, häufiges Wasserlassen; Diagnose: Urodynamik; Therapie: Anticholinergika, Mirabegron, Blasentraining, Botulinumtoxin-Injektion"},
  {"id":280,"cat":"Urologie / Beckenboden","q":"Was ist Harnröhren-Hypermobilität und wie unterscheidet sie sich von ISD?","a":"Hypermobilität: übermässige Beweglichkeit der Urethra bei körperlicher Belastung → Belastungsinkontinenz; Therapie: TVT/TOT; ISD (intrinsic sphincter deficiency): mangelhafter Verschluss der Urethra selbst (schwache Sphinkter); Therapie: Bulkingmittel, Schlingenoperation"},
  {"id":281,"cat":"Perinatologie","q":"Was ist der Triple-Test und wann wird er durchgeführt?","a":"Mütterliches Blut in der 15.–18. SSW; AFP + HCG + Östriol; Risikoberechnung für Trisomie 21, 18 und Neuralrohrdefekte; veraltet – grösstenteils durch Ersttrimesterscreening + NIPT ersetzt; geringere Sensitivität als NIPT"},
  {"id":282,"cat":"Perinatologie","q":"Was ist ein Neuralrohrdefekt und wie kann er verhindert werden?","a":"Spina bifida, Anenzephalie, Enzephalozele; durch unvollständigen Schluss des Neuralrohrs; Präventionsmaßnahme: Folsäure 0,4 mg/Tag (bei erhöhtem Risiko 5 mg) 4 Wochen vor und 12 Wochen nach Konzeption; Diagnose: AFP erhöht, Anatomie-Ultraschall"},
  {"id":283,"cat":"Perinatologie","q":"Was ist die fetale Wachstumsrestriktion (FGR) und wie wird sie überwacht?","a":"Fetales Gewicht <10. Perzentile (schwer: <3.); Überwachung: Doppler der A. umbilicalis, MCA, Ductus venosus; bei frühem Beginn (<32 SSW): stationäre Aufnahme, Lungenreife, Planung der Entbindung; Entbindung bei pathologischem Ductus venosus oder CTG"},
  {"id":284,"cat":"Perinatologie","q":"Was ist die Bedeutung des Ductus venosus-Dopplers?","a":"Blutfluss vom Nabelstrang zur V. cava inferior; pathologischer Fluss (absent/reversed a-wave): schwere fetale Zustandsverschlechterung; Entbindungsindikation bei Frühgeburt; besserer Prädiktor für perinatale Mortalität als Umbilikalisdoppler allein"},
  {"id":285,"cat":"Perinatologie","q":"Was ist Mekoniumaspiration und wie wird sie behandelt?","a":"Aspiration von Mekonium durch den Fetus/das Neugeborene; Risiko: Postterminität, IUGR; Folgen: Atemnotsyndrom (MAS), Pneumothorax, persistierende pulmonale Hypertonie; Therapie: Absaugen, Surfactant, Stickstoffmonoxid, ECMO bei schweren Fällen"},
  {"id":286,"cat":"Perinatologie","q":"Was ist das Atemnotsyndrom des Frühgeborenen (RDS)?","a":"Surfactantmangel bei Unreife der Lunge; Symptome: Tachypnoe, Einziehungen, Stöhnen; Radiologie: Milchglastrübung; Therapie: exogener Surfactant, CPAP, Intubation; Prävention: Betamethason-Lungenreifung vor <34 SSW"},
  {"id":287,"cat":"Perinatologie","q":"Was ist nekrotisierende Enterokolitis (NEC)?","a":"Schwere Darmerkrankung des Frühgeborenen; Ischämie, Entzündung, Nekrose des Darmlumens; Symptome: geblähtes Abdomen, Ernährungsunverträglichkeit, blutige Stühle, Schock; Diagnose: Röntgen (Pneumatosis intestinalis); Therapie: Nahrungskarenz, Antibiotika, ggf. Operation"},
  {"id":288,"cat":"Perinatologie","q":"Was ist intraventrikuläre Hämorrhagie (IVH) beim Frühgeborenen?","a":"Blutung in die periventrikuläre Keimmatrix; Grad I–IV; Grad I/II: meist gutartig; Grad III/IV (mit Ventrikelweitung/Parenchymblutung): schwere Hirnschäden möglich; Prävention: Betamethason, Indomethacin, Verzögerung der Entbindung"},
  {"id":289,"cat":"Perinatologie","q":"Was ist neonatale Hypoglykämie und bei welchen Neugeborenen muss sie erwartet werden?","a":"Blutzucker <2,6 mmol/l in den ersten Lebenstagen; Risikokinder: Mütter mit GDM (Hyperinsulinismus), IUGR, Frühgeborene, LGA-Kinder; Symptome: Zittern, Zyanose, schlechtes Trinken, Bewusstseinsstörung; Therapie: Frühzeitiges Füttern, Glukose oral/i.v."},
  {"id":290,"cat":"Perinatologie","q":"Was ist Rhesusinkompatibilität und wie wird sie verhindert?","a":"Rh-negative Mutter, Rh-positives Kind; mütterliche Anti-D-Antikörper → fetale Hämolyse (Hydrops fetalis, schwere Anämie, Totgeburt); Prävention: Anti-D-Prophylaxe in der 28. SSW und nach Geburt/Intervention bei Rh-negativer Mutter; Therapie: intrauterine Transfusion"},
  {"id":291,"cat":"Perinatologie","q":"Was ist postpartales Hämorrhagierisiko und wie wird es eingeteilt?","a":"PPH: Blutverlust >500 ml nach vaginaler Geburt oder >1000 ml nach Sectio; major PPH: >1000 ml; schwer: >2000 ml; Risikofaktoren: Uterusatonie, Gerinnungsstörung, Plazentareste, Geburtsverletzungen (4 Ts: Tonus, Trauma, Thrombin, Tissue)"},
  {"id":292,"cat":"Perinatologie","q":"Was ist das kongenitale Rötelnsyndrom (CRS)?","a":"Fetale Röteln-Infektion im 1. Trimester; klassische Trias (Gregg): Herzfehler (PDA, VSD), Katarakt, Innenohrschwerhörigkeit; zusätzlich: Mikrozephalie, Hepatosplenomegalie, IUGR; Prävention: MMR-Impfung vor SS"},
  {"id":293,"cat":"Perinatologie","q":"Was ist das Down-Syndrom (Trisomie 21) und wie wird es diagnostiziert?","a":"Karyotyp 47,XX+21 oder 47,XY+21; Symptome: mentale Retardierung, Hypotonie, Epikanthus, flaches Gesicht, Herzfehler (ASD, VSD), Duodenalatresie; Diagnose präpartal: NIPT, Ersttrimesterscreening, Amniozentese; Risiko steigt mit mütterlichem Alter"},
  {"id":294,"cat":"Perinatologie","q":"Was ist das Edwards-Syndrom (Trisomie 18)?","a":"Karyotyp 47,XX/XY+18; schwere Fehlbildungen: Herzfehler, Ösophagusatresie, Rocker-bottom-Füsse, Fäuste mit Überlappungsfinern; meist letal (50% <1 Woche); Diagnose: Ultraschall (Omplhazele, IUGR, Herzfehler), Amniozentese"},
  {"id":295,"cat":"Gynäkologie","q":"Was ist die Hysterektomie und welche Typen gibt es?","a":"Entfernung des Uterus; totale Hysterektomie: Uterus + Zervix; subtotale: nur Uterus (Zervix bleibt); radikale Hysterektomie (Wertheim): zusätzlich Parametrien, Scheidenmanschette, pelvine LK; Zugangswege: vaginal, abdominal, laparoskopisch (TLH)"},
  {"id":296,"cat":"Gynäkologie","q":"Was ist die Salpingektomie und wann ist sie indiziert?","a":"Entfernung der Tube; Indikationen: Eileiterschwangerschaft, Hydrosalpinx (vor IVF), prophylaktische Salpingektomie bei BRCA-Mutation (reduziert Ovarialkarzinom-Risiko durch Entfernung der häufigen Ursprungsregion des serösen high-grade OC)"},
  {"id":297,"cat":"Gynäkologie","q":"Was ist eine Oophorektomie und was sind die Folgen?","a":"Entfernung des Ovars; bilateral: sofortige chirurgische Menopause (Östrogenmangel, Osteoporose, kardiovaskuläre Risiken); Indikationen: Ovarialkarzinom, BRCA-prophylaktisch, benignes tumorös verändertes Ovar; HRT nach prophylaktischer Oophorektomie empfohlen bis natürliches Menopausenalter"},
  {"id":298,"cat":"Gynäkologie","q":"Was ist eine laparoskopische Operation und welche Komplikationen können auftreten?","a":"Minimal-invasive Operation durch Bauchdecke mit CO2-Pneumoperitoneum; Komplikationen: Gefässverletzungen (A. iliaca!), Darmverletzungen, Harnleiterverletzungen, Hautemphysem; Vorteil: weniger Schmerzen, kürzerer Aufenthalt, weniger Adhäsionen"},
  {"id":299,"cat":"Gynäkologie","q":"Was ist der Unterschied zwischen diagnostischer und operativer Laparoskopie?","a":"Diagnostisch: reine Inspektion der Bauchhöhle (Tubenpatenz, Endometriose-Staging); operativ: zusätzliche Eingriffe (Zystektomie, Adhäsiolyse, Myomektomie, Adnexektomie); heute meist direkt operativ wenn Befund vorhergesagt"},
  {"id":300,"cat":"Geburtshilfe","q":"Was ist eine Vakuumextraktion (Saugglocke) und wann wird sie eingesetzt?","a":"Operative vaginale Entbindung mittels Vakuumglocke am Kopf; Indikationen: ähnlich wie Forceps; Vorteile: weniger mütterliches Trauma; Nachteile: Kephalhaematom, Subgaleale Blutung beim Neugeborenen; Voraussetzungen: MM vollständig, eingetreten, Schädellage"},
  {"id":301,"cat":"Geburtshilfe","q":"Was ist Frühgeburtsprävention und welche Massnahmen sind evidenzbasiert?","a":"Evidenzbasiert: vaginales Progesteron bei CL <25 mm (ohne BEL-Anamnese), Cerclage bei kurzer Zervix + Anamnese für Spätabort; Pessar: kontrovers; Magnesiumprophylaxe (<32 SSW zur Neuroprotektion; Bettruhe: nicht evidenzbasiert"},
  {"id":302,"cat":"Geburtshilfe","q":"Was ist die Behandlung einer schwangeren Patientin mit Thrombose?","a":"Therapeutische Antikoagulation mit NMH (z.B. Enoxaparin, gewichtsadaptiert); KEINE Kumarinderivate im 1. Trimester (Embryopathie) und 3. Trimester (Blutungsrisiko); postpartal: Umstellung auf Kumarinderivate möglich; Stillen: NMH und Warfarin erlaubt"},
  {"id":303,"cat":"Endokrinologie / Hormone","q":"Was ist das Zollinger-Ellison-Syndrom und hat es gynäkologische Relevanz?","a":"Gastrinproduzierendes Pankreastumor (Gastrinom); keine direkte gynäkologische Relevanz; jedoch: Multiple endokrine Neoplasie Typ 1 (MEN1) beinhaltet Pankreastumoren, Parathormonausschüttung und Hypophysenadenome; bei MEN1: Familienscreening empfohlen"},
  {"id":304,"cat":"Gynäkologie","q":"Was ist das Premenstruelle Syndrom (PMS) und wie wird es behandelt?","a":"Zyklusabhängige körperliche und psychische Symptome in der Lutealphase; Symptome: Dysphorie, Stimmungsschwankungen, Mastodynie, Ödem, Blähungen; schwere Form: PMDD (premenstrual dysphoric disorder); Therapie: KOK (Drospirenon), SSRI, Sporttherapie, GnRH-Analoga bei schwerer Form"},
  {"id":305,"cat":"Onkologie","q":"Was sind die Nebenwirkungen von Tamoxifen?","a":"Selektiver Östrogenrezeptormodulator (SERM); Nebenwirkungen: Hitzewallungen, thromboembolische Ereignisse, Endometriumhyperplasie/-karzinom (uterine Stimulation), Katarakt, Stimmungsschwankungen; Kontrolle: jährliche Endometrium-Sonographie"},
  {"id":306,"cat":"Onkologie","q":"Was ist Neoadjuvante Chemotherapie beim Ovarialkarzinom?","a":"Chemotherapie (Carboplatin + Paclitaxel) vor Operation (Intervall-Debulking); Indikation: schlechter Allgemeinzustand, nicht primär resektabel (FIGO III/IV); Ziel: Tumorverkleinerung dann Op; ähnliche Gesamtüberlebensrate wie primäre Op"},
  {"id":307,"cat":"Gynäkologie","q":"Was sind Zeichen und Symptome des akuten Abdomens in der Gynäkologie?","a":"Plötzlich einsetzende starke Bauchschmerzen; gynäkologische Ursachen: EUG-Ruptur, Ovarialtorsion, Ovarialzystenruptur, Myomdegeneration, tuboovarialer Abszessruptur; Differentialdiagnosen: Appendizitis, Ileus, Pankreatitis, Nierenkolik"},
  {"id":308,"cat":"Endokrinologie / Hormone","q":"Was ist eine Makroprolaktinämie?","a":"Prolaktin v.a. als Makroprolaktin (Prolaktin-IgG-Komplex) im Blut; erhöhter Prolaktinspiegel ohne klinische Symptome; Differenzierung durch PEG-Fällung (Polyethylenglykol); keine Therapie nötig; wichtig zur Vermeidung unnötiger MRI-Hypophysen-Abklärung"},
  {"id":309,"cat":"Geburtshilfe","q":"Was ist ein Krampfanfall in der Schwangerschaft ausserhalb der Eklampsie?","a":"Differentialdiagnosen: Epilepsie (bekannte Epilepsie oder Erstmanifestation), Eklampsie (>20 SSW + Hypertonie), thrombotische thrombozytopenische Purpura (TTP), zerebrale Sinusthrombose, Hypoglykämie; Abklärung: Blutdruck, Labor, zerebrale Bildgebung"},
  {"id":310,"cat":"Geburtshilfe","q":"Was ist Methyldopa und wie wird es in der SS eingesetzt?","a":"Zentraler α2-Agonist; First-Line-Antihypertensivum in der SS; hemmt Sympathikusaktivität; Dosierung: 250–3000 mg/Tag in 2–3 Dosen; Nebenwirkungen: Sedation, Depression, Lebertoxizität; passiert die Plazenta, aber sicher für den Fetus"},
  {"id":311,"cat":"Gynäkologie","q":"Was ist ein Zervixpolyp und wie wird er behandelt?","a":"Gutartige Ausstülpung der Zervixschleimhaut; meist asymptomatisch oder Kontaktblutungen; Diagnose: Spekulum; Therapie: ambulante Entfernung (Abdrehen) mit Histologie; kaum maligne Entartung, aber Ausschluss Zervixkarzinom wichtig"},
  {"id":312,"cat":"Endokrinologie / Hormone","q":"Welche nicht-hormonellen Therapien helfen bei Vulvaatrophie?","a":"Lokale Östrogen-Cremes/Ovula (First-Line): geringe systemische Wirkung; OSPEMIFENE (SERM, oral): bei Kontraindikation für lokales Östrogen; Feuchtigkeitscremen (Replens); Lasertherapie (CO2/Er:YAG): Evidenz begrenzt; regelmässiger GV schützt vor Atrophie"},
  {"id":313,"cat":"Urologie / Beckenboden","q":"Was ist eine Harnröhrenkarunkel?","a":"Gutartige, dunkelrote Wucherung an der hinteren Harnröhrenmündung; häufig postmenopausal (Östrogenmangelzustand); Symptome: Dysurie, Blutung, Schmerzen; Therapie: lokales Östrogen, selten operative Exzision"},
  {"id":314,"cat":"Urologie / Beckenboden","q":"Was ist der Unterschied zwischen Drang- und Belastungsinkontinenz in der Urodynamik?","a":"Belastungsinkontinenz: Urinverlust bei Druckanstieg ohne Detrusorkontrakion; Urethrawiderstand unzureichend; Dranginkontinenz: unwillkürliche Detrusorkontraktionen → Druckanstieg überwindet Urethrawiderstand; gemischte Formen häufig"},
  {"id":315,"cat":"Infektionen / STI","q":"Was ist das Fitz-Hugh-Curtis-Syndrom und welche Erreger verursachen es?","a":"Perihepatitis bei PID; häufigste Erreger: Chlamydia trachomatis (>60%) und Neisseria gonorrhoeae; violinstrings-Verwachsungen zwischen Leber und Bauchdecke; Symptome: Schmerzen re. Oberbauch; Therapie: Antibiotika der PID"},
  {"id":316,"cat":"Kontrazeption","q":"Was ist das Ogino-Knaus-Prinzip (Kalender-Methode)?","a":"Natürliche Verhütung durch Bestimmung der fruchtbaren Tage anhand des Zyklus; Ovulation ca. 12–16 Tage vor nächster Menstruation; fruchtbar: 5 Tage vor bis 2 Tage nach Ovulation; Pearl-Index: 9 (typical use); unsicher, da Zyklen variabel"},
  {"id":317,"cat":"Gynäkologie","q":"Was ist Koagulation vs. Fulguration in der Gynäkologie?","a":"Koagulation: direkter Kontakt zwischen Elektrode und Gewebe; thermokoagulation; Fulguration: Lichtbogenentladung ohne Kontakt; Karbonisation; in der Hysteroskopie für Myomresektion, Endometrium-Ablation, Polypenresektion genutzt"},
  {"id":318,"cat":"Gynäkologie","q":"Was ist Endometriumablation und wann wird sie eingesetzt?","a":"Destruktion des Endometriums zur Therapie der Hypermenorrhoe; Methoden: Resektoskopie (TCRE), thermale Ablation (NovaSure), Kryoablation; Indikation: benigne Hypermenorrhoe nach abgeschlossenem Kinderwunsch; keine Empfängnisverhütung danach sicher!"}
];
export const CATEGORIES = ["Alle Themen", ...[...new Set(CARDS.map(c=>c.cat))].sort()];